/* Atlas : océans, mers, fleuves et rivières, lacs — généré par tools/atlas-build-themes.mjs. Chiffres : Wikidata (CC0). Textes : Vikidia / Wikipédia (CC BY-SA 4.0), lien par fiche. */
window.MQ_ATLAS_T=window.MQ_ATLAS_T||{};Object.assign(window.MQ_ATLAS_T,{
"oceans":{"ocean-arctique":{"n":"Océan Arctique","t":"océan","km2":14056000,"bref":["Entourant le pôle Nord, autrefois appelé océan Glacial arctique, l'océan Arctique a une superficie d’environ 5 200 000 km2. C'est le plus petit des quatre océans. En ajoutant les mers bordières, la superficie de l'ensemble océanique atteint alors 14 090 000 km2 le reste étant formé d’îles (dont certaines de grande taille). Les mers arctiques baignent les côtes nord-ouest de la Norvège, les côtes septentrionales de la Russie, de l'Alaska, du Canada, du Groenland et de l'Islande. L'océan Arctique est, lui, limité le plus souvent par des îles, que ce soit sous la forme d'archipels (Svalbard , archipel François-Joseph etc.) ou de terres isolées (ile Wrangel). L'océan Arctique ne touche un continent qu'en un seul endroit, nommé Point Barrow, et situé en Alaska."],"src":"https://fr.vikidia.org/wiki/Oc%C3%A9an_Arctique","sw":"v","q":"Q788"},"ocean-atlantique":{"n":"Océan Atlantique","t":"océan","km2":106460000,"bref":["L’océan Atlantique, souvent nommé l’Atlantique et parfois l’Océan (mot vieilli, employé par opposition à Méditerranée), est le deuxième océan de la Terre par la superficie après l'océan Pacifique."],"src":"https://fr.vikidia.org/wiki/Oc%C3%A9an_Atlantique","sw":"v","q":"Q97"},"ocean-austral":{"n":"Océan Austral","t":"océan","km2":20327000,"bref":["Avec une superficie de 20 327 000 km² et des rivages totalisant 17 968 km sur le continent antarctique, l'océan Austral (appelé autrefois océan Antarctique ou océan Glacial antarctique) est né assez récemment d'une construction de l'esprit : en réunissant les parties des trois océans principaux (océan Atlantique, océan Indien et océan Pacifique) situées en dessous du 60e degré de latitude Sud."],"src":"https://fr.vikidia.org/wiki/Oc%C3%A9an_Austral","sw":"v","q":"Q7354"},"ocean-indien":{"n":"Océan Indien","t":"océan","km2":70560000,"bref":["L'océan Indien doit son nom au fait qu'il est limité au nord par l'Inde, en Asie. Les autres grandes masses terrestres qu'il borde sont l'Afrique et l'Australie, respectivement à l'ouest et à l'est . L'océan est bordé au sud par le continent Antarctique. Sa plus grande dimension, entre le cap des Aiguilles (Afrique du Sud) et le cap Sud-Est (Tasmanie, Australie), atteint 9 787 km. Du nord au sud, l'océan Indien mesure 8 470 km de longueur depuis le ras Hafun, en Somalie, à la Terre d'Enderby sur le continent antarctique.","Il est appelé océan Indien depuis l'antiquité grecque.","Á la périphérie de l'océan se trouvent des mers bordières comme la mer d'Arabie, le golfe du Bengale ou la mer d'Andaman.","Contrairement à ce que laisse supposer la carte ci-dessus, le détroit de Malacca, les mers de Java, de Bali et de Florès (teintées en bleu foncé par erreur) se situent dans la zone Pacifique. Inversement, la mer d'Arafura, au nord de l'Australie, teintée en bleu clair, appartient pourtant bien à l'océan Indien. La mer de Corail, mer bordière de l'océan Pacifique, ne commence qu'à partir de l'extrémité nord-ouest de la péninsule du cap d'York (en Australie, nord du Queensland), en comprenant les eaux du détroit de Torrès."],"src":"https://fr.vikidia.org/wiki/Oc%C3%A9an_Indien","sw":"v","q":"Q1239"},"ocean-pacifique":{"n":"Océan Pacifique","t":"océan","km2":161760000,"bref":["L'océan Pacifique est l'océan le plus vaste du globe terrestre. Le Pacifique fait partie de l'océan mondial et il comporte deux océans : le Pacifique nord et le Pacifique sud. Le Pacifique s'étend sur une surface de 165 250 000 km2, soit environ un tiers de la surface totale de la Terre et 20,45 millions km2 de plus que la surface totale de la planète Mars. Sa superficie est également supérieure à celle de l'ensemble des terres émergées de la planète. Il comprend la Polynésie et la Micronésie dans leur totalité. Avec ses mers bordières, il baigne la Mélanésie tandis que ses propres eaux bordent des îles et archipels qui font traditionnellement partie de l'Asie insulaire (Honshū, Hokkaidō et les Kouriles). Plusieurs de ses mers bordières baignent l'Insulinde pendant que d'autres espaces maritimes, comme la mer de Tasman, la mer de Corail et l'océan Indien, bordent l'Australasie."],"src":"https://fr.wikipedia.org/wiki/Oc%C3%A9an_Pacifique","sw":"w","q":"Q98"}},
"mers":{"baie-de-baffin":{"n":"baie de Baffin","t":"mer","km2":689000,"bref":["La baie de Baffin est un espace maritime périphérique de l'océan Arctique situé entre l'île de Baffin, l'île Bylot, l'île Devon et l'île d'Ellesmere d'une part et le Groenland d'autre part. Les quatre premières îles sont en territoire canadien et le Groenland constitue une nation du royaume de Danemark. La superficie de la baie est de 689 000 kilomètres carrés."],"src":"https://fr.vikidia.org/wiki/Baie_de_Baffin","sw":"v","q":"Q37040","pays":["CA","GL"],"c":["amerique-nord"]},"bassin-levantin":{"n":"bassin Levantin","t":"mer","km2":320000,"bref":["Le bassin Levantin est une division du bassin oriental de la mer Méditerranée et qui correspond à sa partie la plus à l'est (Turquie méridionale, Chypre, Moyen-Orient). Il est parfois appelé mer Levantine ou mer du Levant, mais ces dernières dénominations ne sont pas utilisées par l'Organisation hydrographique internationale. Le bassin doit son nom au « Levant », qui était à l'origine un mot issu du français médiéval signifiant « orient ». Le bassin Levantin est bordé au nord et à l'est par les côtes asiatiques du Moyen-Orient (Proche-Orient) au nord-ouest par les îles de l'arc égéen, à l'ouest par une ligne reliant l'île de Gávdos à l'extrémité est du djebel Akhdar (ra's At Tin), en Libye, et au sud par les côtes africaines."],"src":"https://fr.wikipedia.org/wiki/Bassin_Levantin","sw":"w","q":"Q748696","pays":["TR","SY","LB","IL","EG","CY","JO","PS","LY","GR"],"c":["asie","europe","afrique"]},"golfe-de-finlande":{"n":"golfe de Finlande","t":"mer","km2":29500,"bref":["Le golfe de Finlande est un bras de la mer Baltique, qui baigne la Finlande au nord, la Russie à l'est, vers le delta de la Neva, et l'Estonie au sud.","Les grandes villes qui bordent le golfe sont Helsinki (en Finlande), Vyborg et Saint-Pétersbourg (Russie), et Tallinn (en Estonie)."],"src":"https://fr.vikidia.org/wiki/Golfe_de_Finlande","sw":"v","q":"Q14686","pays":["RU","EE","FI"],"c":["asie","europe"]},"golfe-persique":{"n":"golfe Persique","t":"mer","km2":251000,"bref":["Le golfe Persique est situé au Moyen-Orient, entre l'Iran, le Sud-Est de l'Irak et la péninsule Arabique. Il mesure environ 1125 km de long pour une largeur variant de 55 à 365 km . Sa superficie est de 237 000 km². Sa profondeur moyenne est de 37 m. Le golfe contient dans ses eaux le détroit d'Ormuz, long de 212 kilomètres, qui permet de rejoindre le golfe d'Oman.","Au nord, le golfe Persique reçoit les eaux du Tigre et de l'Euphrate, qui y forment un delta marécageux. La côte arabique est basse et bordée de lagunes. La faible profondeur des eaux facilite l'extraction du pétrole sous-marin (à Bahreïn et au Koweït). Les gisements pétrolifères de l'Arabie saoudite sont terrestres, mais proches des côtes. Actuellement, c'est l'une des plus importantes régions économiques du monde car elle est une très grande productrice de pétrole (Koweït, Qatar, Bahreïn, Émirats arabes unis, Arabie saoudite) et l'un des lieux de transit des pétroles irakien et iranien."],"src":"https://fr.vikidia.org/wiki/Golfe_Persique","sw":"v","q":"Q34675","pays":["IR","IQ","KW","BH","QA","SA","AE","OM"],"c":["asie"]},"manche":{"n":"Manche","t":"mer","km2":75000,"bref":["La Manche est la mer qui se trouve entre l'Angleterre et la France. Les Britanniques l'appellent the English Channel, ou plus simplement the Channel. Les Bretons quand à eux l'appellent Mor Breizh (mer de Bretagne en breton). La Manche permet la liaison entre l'océan Atlantique et la mer du Nord grâce à un détroit : le détroit du pas de Calais. La superficie de la Manche est de 75 000 km². C'est l'une des mers les plus fréquentées du monde.","La Manche repose sur un socle cristallin recouvert par un bassin sédimentaire gigantesque (ce bassin s'étend sur le bassin de Londres et le Bassin parisien, puisqu'on retrouve de part et d'autre de la Manche les mêmes couches sédimentaires). Ce bassin, attaqué par les eaux de l'Atlantique, a été envahi par la mer après la dernière glaciation, il y a environ 15 000 ans. La profondeur de la Manche est faible (entre 50 et 100m), sauf au large de l'île de Guernesey où existe une « fosse » de 172 m de profondeur."],"src":"https://fr.vikidia.org/wiki/Manche_(mer)","sw":"v","q":"Q34640","pays":["GB","FR"],"c":["europe"]},"mer-adriatique":{"n":"mer Adriatique","t":"mer","km2":138595,"bref":["La mer Adriatique est une partie de la mer Méditerranée située entre l'Italie et les pays de l'ex-Yougoslavie. Elle est limitée au nord-ouest par la partie nord de l'Italie et s'ouvre au sud-est par le canal d'Otrante sur la mer Ionienne, à la hauteur de l'Albanie.","La mer Adriatique a une superficie de 131 500 km2. Elle mesure 800 kilomètres du nord au sud et 220 kilomètres dans sa plus grande largeur. Elle est peu profonde au nord â cause des apports considérables en alluvions par le Pô et l'Adige. Elle borde l'Italie, la Slovénie, la Croatie, la Bosnie-Herzégovine (seulement sur une vingtaine de kilomètres), le Monténégro et l'Albanie. Au niveau de Bari-Durrës, elle est profonde de 1 280 mètres. Le fond se relève jusqu'à moins de 600 mètres dans le canal d'Otrante. Les marées peuvent atteindre un mètre dans le golfe de Venise."],"src":"https://fr.vikidia.org/wiki/Mer_Adriatique","sw":"v","q":"Q13924","pays":["IT","SI","HR","BA","ME","AL"],"c":["europe"]},"mer-caspienne":{"n":"mer Caspienne","t":"mer","km2":386400,"bref":["La mer Caspienne est une mer fermée d'Europe orientale et d'Asie occidentale. Les rives comprises entre le delta du fleuve Oural et l'extrémité orientale du Caucase sont généralement considérées comme faisant partie des limites séparant l'Europe et l'Asie.","C'est la plus grande mer fermée au monde, avec une surface de 371 000 km² pour un volume de plus de 78 000 km³. Si sa voisine la mer Noire est plus grande aussi bien en surface qu'en volume, elle n'est pas une mer fermée puisqu'elle communique avec la mer Méditerranée (indirectement, par la mer de Marmara).","Elle est beaucoup moins salée que les mers et océans habituels (environ trois fois moins, 12 g de sels par litre contre une moyenne de 35 pour les océans). Son état de mer fermée la prive du statut juridique de mer. En effet, ne communiquant pas avec les autres mers et océans, le droit maritime international ne s'y applique pas. Pourtant, elle est un axe maritime international. Les pays riverains ont donc été amenés à définir une réglementation, la Convention sur le statut de la mer Caspienne, concernant la circulation des navires sur cette mer. Cette convention emprunte pourtant au droit de la mer."],"src":"https://fr.vikidia.org/wiki/Mer_Caspienne","sw":"v","q":"Q5484","pays":["RU","KZ","TM","IR","AZ"],"c":["asie","europe"]},"mer-d-arabie":{"n":"mer d'Arabie","t":"mer","km2":3862000,"bref":["La mer d’Arabie ou mer d'Oman est une mer bordière de l'océan Indien située entre la pointe de la corne de l'Afrique, la péninsule arabique à l'ouest, le Pakistan au nord, l'Inde à l'est, les îles Laquedives à l'est-sud-est et les îles Maldives au sud-est. Ces deux archipels ne font pas partie de la mer d'Arabie mais de la mer des Laquedives, située au sud-est. Sa profondeur moyenne est de 2 734 mètres."],"src":"https://fr.vikidia.org/wiki/Mer_d'Arabie","sw":"v","q":"Q58705","pays":["IN","IR","MV","OM","PK","SO"],"c":["asie","afrique"]},"mer-d-argentine":{"n":"mer d'Argentine","t":"mer","km2":940000,"bref":["La mer d'Argentine (en espagnol : Mar Argentino) est une mer de l'océan Atlantique Sud entre l'estuaire du Río de la Plata (latitude 35 degrés Sud) et le banc Burdwood (es) (environ latitude 54,30 degrés Sud). Sa largeur varie entre 210 km au large de Mar del Plata et 850 km à la latitude des Malouines. Le littoral continental s'étend sur 4 725 km.","Cette mer d'une superficie de 940 000 km2 et d'une profondeur moyenne de 200 m, couvre principalement le plateau continental de l'Argentine."],"src":"https://fr.wikipedia.org/wiki/Mer_d'Argentine","sw":"w","q":"Q970130","pays":["AR"],"c":["amerique-sud"]},"mer-d-azov":{"n":"mer d'Azov","t":"mer","km2":37600,"bref":["La mer d'Azov est une mer bordière de la mer Noire, dans le Sud-Est de l'Europe. Elle s'ouvre sur la mer Noire par le détroit de Kertch. Elle baigne les côtes de l'Ukraine et de la Russie. Elle s'étend sur une superficie de 37 600 km2","La mer d'Azov est alimentée par le Don et le Kouban. Les eaux de cette mer sont saumâtres (très peu salées) et peu profondes (10 mètres en moyenne) ; dans l'Antiquité, la mer d'Azov était considérée comme un lac bordé de marais, appelé Palus Meotis (« lac Méotide »).","Aujourd'hui l'eutrophisation d'origine agricole et urbaine est un des problèmes importants de la mer d'Azov.","La mer d'Azov est le débouché naturel de la région minière et industrielle du Donbass. Les ports principaux sont Rostov-sur-le-Don et Azov."],"src":"https://fr.vikidia.org/wiki/Mer_d'Azov","sw":"v","q":"Q35000","pays":["RU","UA"],"c":["asie","europe"]},"mer-d-irlande":{"n":"mer d'Irlande","t":"mer","km2":100000,"bref":["La mer d'Irlande (en anglais : Irish Sea ; en irlandais : Muir Éireann ; en mannois : Y Keayn Yernagh ; en gallois : Môr Iwerddon ; en gaélique écossais : Muir Èireann ; en scots : Erse Sea ; en scots d'Ulster : Airish Sea) est un bras de mer de l'archipel des îles Britanniques séparant les îles d'Irlande à l'ouest et de Grande-Bretagne à l'est. S'étendant sur 46 007 km2, elle communique avec les mers intérieures de la côte ouest de l'Écosse par le canal du Nord au nord-ouest et avec la mer Celtique par le canal Saint-Georges au sud, ces mers étant des mers bordières de l'océan Atlantique."],"src":"https://fr.wikipedia.org/wiki/Mer_d'Irlande","sw":"w","q":"Q41735","pays":["GB","IE","IM"],"c":["europe"]},"mer-d-irminger":{"n":"mer d'Irminger","t":"mer","km2":780000,"bref":["La mer d'Irminger est une partie de l’océan Atlantique située au sud-est du Groenland et au sud-ouest de l’Islande au débouché sud du détroit de Danemark. Elle communique, au-delà du cap Farvel (cap le plus au sud du Groenland), avec la mer du Labrador.","Le courant d'Irminger, composante du Gulf Stream y passe.","Les deux toponymes doivent leur nom au vice-amiral, ministre de la Marine et hydrographe danois Carl Irminger (da) (1802-1888) qui conduisit une expédition scientifique dans la zone en 1854."],"src":"https://fr.wikipedia.org/wiki/Mer_d'Irminger","sw":"w","q":"Q1542675","pays":["GL","IS"],"c":["amerique-nord","europe"]},"mer-de-bali":{"n":"mer de Bali","t":"mer","km2":45000,"bref":["La mer de Bali (en indonésien laut Bali) est une petite mer située dans le centre de l'archipel indonésien, au sud-est de la mer de Java et au sud-ouest de la mer de Florès.","La mer se situe dans l'hémisphère austral mais reste proche de l'équateur."],"src":"https://fr.vikidia.org/wiki/Mer_de_Bali","sw":"v","q":"Q277014","pays":["ID"],"c":["asie"]},"mer-de-banda":{"n":"mer de Banda","t":"mer","km2":470000,"bref":["La mer de Banda est une mer marginale d'Indonésie. Son nom provient des îles Banda, situées dans l'Est de la mer, au sud de l'île de Seram.","Elle est une mer bordière de l'océan Pacifique bien qu'elle n'ait pas de limite commune avec cet océan. Aussi la mer est-elle considérée comme faisant partie des « archipels orientaux » ou Insulinde, un sous-ensemble de l'océan Pacifique."],"src":"https://fr.vikidia.org/wiki/Mer_de_Banda","sw":"v","q":"Q171510","pays":["ID","TL"],"c":["asie"]},"mer-de-beaufort":{"n":"mer de Beaufort","t":"mer","km2":178000,"bref":["La mer de Beaufort est un espace maritime situé au Canada, plus précisément dans les Territoires du Nord-Ouest, et en Alaska. La mer doit son nom â l'hydrographe britannique sir Francis Beaufort (1774-1857), devenu par la suite contre-amiral dans la Royal Navy."],"src":"https://fr.vikidia.org/wiki/Mer_de_Beaufort","sw":"v","q":"Q131274","pays":["CA","US"],"c":["amerique-nord"]},"mer-de-bering":{"n":"mer de Béring","t":"mer","km2":2300000,"bref":["La mer de Béring est une mer marginale de l'océan Pacifique située entre le Nord-Est de la Russie et l'Alaska. Elle porte le nom de l'explorateur danois Vitus Béring qui fut l'un des premiers européens à la parcourir. Parmi les nombreuses îles que cette mer abrite figurent les îles Aléoutiennes, la Grande et la Petite Diomède et l'île Saint-Lawrence."],"src":"https://fr.vikidia.org/wiki/Mer_de_B%C3%A9ring","sw":"v","q":"Q44725","pays":["US","RU"],"c":["amerique-nord","asie","europe"]},"mer-de-bismarck":{"n":"mer de Bismarck","t":"mer","km2":361000,"bref":["La mer de Bismarck est une mer bordière comprise entre la côte nord-est de la Papouasie-Nouvelle-Guinée et les côtes septentrionales des principales îles formant l'archipel Bismarck (Îles de l'Amirauté, Nouvelle-Hanovre, Nouvelle-Irlande et Nouvelle-Bretagne). Elle communique au sud-ouest avec la mer des Salomon par les détroits de Vitiaz et de Dampier (en mer des Salomon) et au sud-est par le canal Saint-Georges (en mer de Bismarck). Sous contrôle allemand de 1884 à 1919, l'ensemble des îles prit le nom de « Nouvelle-Guinée allemande ». La mer porte le nom du chancelier Otto von Bismarck, artisan de l'unification allemande."],"src":"https://fr.vikidia.org/wiki/Mer_de_Bismarck","sw":"v","q":"Q199436","pays":["PG"],"c":["oceanie"]},"mer-de-chine-meridionale":{"n":"mer de Chine méridionale","t":"mer","km2":3500000,"bref":["La mer de Chine méridionale ou mer de Chine du Sud est une mer asiatique entourée par la Chine au nord, par la mer de Chine orientale et Taïwan au nord-nord-est, par les Philippines à l'est, par l'île de Bornéo au sud, par l'Indonésie au sud-sud-ouest, par la péninsule Malaise au sud-ouest, par le golfe de Thaïlande à l'ouest-sud-ouest et par le Vietnam à l'ouest et au nord-ouest."],"src":"https://fr.vikidia.org/wiki/Mer_de_Chine_m%C3%A9ridionale","sw":"v","q":"Q37660","pays":["PH","BN","VN","TW","MY","KH","CN","ID"],"c":["asie"]},"mer-de-davis":{"n":"mer de Davis","t":"mer","km2":21000,"bref":["La mer de Davis est une mer de l'océan Indien.","Elle est située le long de la côte est du continent antarctique entre la barrière de glace ouest et la barrière de Shackleton.","Découverte par l'expédition antarctique australasienne (1911 - 1914), elle fut nommée ainsi par Douglas Mawson en l'honneur du capitaine John King Davis, navigateur de l’Aurora et commandant en second de l'expédition."],"src":"https://fr.wikipedia.org/wiki/Mer_de_Davis","sw":"w","q":"Q509321"},"mer-de-flores":{"n":"mer de Florès","t":"mer","km2":240000,"bref":["La mer de Florès est une mer d'Indonésie qui s'étend entre la côte méridionale de Sulawesi Sud, sur l'île de Célèbes, au nord, l'île Jailamu (en indonésien pulau Jailamu) et l'île Kapoposangbali dans l'archipel Tengah à l'ouest, les îles de Sumbawa, Batan, Komodo","et Florès au sud et enfin l'archipel Selayar à l'est.","D'une superficie d'environ 111 280 kilomètres carrés , d'une longueur ouest-est maximale de 630 kilomètres se réduisant à 272 kilomètres en son milieu, elle communique à l'ouest avec la mer de Java, au sud-ouest avec la mer de Bali et la mer de Savu enfin à l'est avec la mer de Banda."],"src":"https://fr.vikidia.org/wiki/Mer_de_Flor%C3%A8s","sw":"v","q":"Q150370","pays":["ID"],"c":["asie"]},"mer-de-java":{"n":"mer de Java","t":"mer","km2":320000,"bref":["La mer de Java est une mer épicontinentale et marginale bordière de l'océan Pacifique. Elle s'étend sur une longueur ouest-est de 1 450 km et une largeur nord-sud de 420 km pour une surface de 433 000 km2."],"src":"https://fr.vikidia.org/wiki/Mer_de_Java","sw":"v","q":"Q49364","pays":["ID"],"c":["asie"]},"mer-de-kara":{"n":"mer de Kara","t":"mer","km2":880000,"bref":["La mer de Kara est une mer épicontinentale de l'océan Arctique. Elle sépare la Nouvelle-Zemble (à l'ouest-sud-ouest) et la terre du Nord (au nord-est). À l'ouest de la Nouvelle-Zemble s'étend la mer de Barents, au nord l'océan Arctique et à l'est de la terre du Nord se trouve la mer des Laptev. Le seul pays bordé par la mer de Kara est la Russie."],"src":"https://fr.vikidia.org/wiki/Mer_de_Kara","sw":"v","q":"Q33629","pays":["RU"],"c":["asie","europe"]},"mer-de-l-entente":{"n":"mer de l'Entente","t":"mer","km2":258000,"bref":["La mer de la Coopération, ou mer de l'Entente anciennement mer de Mackenzie, est une mer de l’océan Indien située près de l'Antarctique. Elle est située entre la mer des Cosmonautes (à l'ouest) et la mer de Davis (à l'est). Au sud, elle baigne la côte de la Terre de la Princesse-Élisabeth."],"src":"https://fr.wikipedia.org/wiki/Mer_de_la_Coop%C3%A9ration","sw":"w","q":"Q2085564"},"mer-de-la-scotia":{"n":"mer de la Scotia","t":"mer","km2":900000,"bref":["La mer de Scotia ou mer du Scotia est une mer de l'océan Atlantique Sud. Elle est comprise entre l'île des États (Argentine), la Géorgie du Sud, les Sandwich du Sud, les Orcades du Sud et l'île Clarence, la plus orientale des Shetland du Sud."],"src":"https://fr.wikipedia.org/wiki/Mer_de_Scotia","sw":"w","q":"Q204703","pays":["GS"],"c":["amerique-sud"]},"mer-de-lazarev":{"n":"mer de Lazarev","t":"mer","km2":929000,"bref":["La mer de Lazarev est une mer de l'océan Atlantique sud. Elle est située entre la mer de Weddell (à l'ouest) et la mer de Riiser Larsen (à l'est). Au sud, elle baigne la côte de la Terre de la Reine-Maud à l'est du continent antarctique. Elle est nommée d'après l'amiral et explorateur russe Mikhaïl Lazarev (1788-1851)."],"src":"https://fr.wikipedia.org/wiki/Mer_de_Lazarev","sw":"w","q":"Q1576063"},"mer-de-petchora":{"n":"mer de Petchora","t":"mer","km2":89574,"bref":["La mer de Petchora (russe : Печо́рское мо́ре, ou Pechorskoï More) est une étendue d'eau située au sud-est de la mer de Barents, au nord-ouest de la Russie. La limite occidentale de la mer est l'île Kolgouïev, tandis qu'elle est délimitée à l'est par les côtes occidentales de l'île Vaïgatch et la péninsule Iougorski, et au nord par l'extrémité sud de la Nouvelle-Zemble.","La profondeur de la mer de Petchora est relativement faible, sa profondeur moyenne n'étant que de 6 m. Sa profondeur maximale est de 210 m. Dans la partie méridionale de la mer de Petchora, la courant Kolgouïev coule en direction de l'est. La mer comporte quelques îles situées à proximité des côtes, la plus importante d'entre elles étant l'île Dolgui."],"src":"https://fr.wikipedia.org/wiki/Mer_de_Petchora","sw":"w","q":"Q217501","pays":["RU"],"c":["asie","europe"]},"mer-de-ross":{"n":"mer de Ross","t":"mer","km2":637000,"bref":["La mer de Ross est une baie profonde de l'océan Pacifique sud bordant le continent Antarctique entre la terre Marie Byrd à l'est et la terre de Victoria à l'ouest. Elle porte le nom de James Clark Ross qui commandait l'expédition qui l'a découverte."],"src":"https://fr.wikipedia.org/wiki/Mer_de_Ross","sw":"w","q":"Q164466"},"mer-de-savu":{"n":"mer de Savu","t":"mer","km2":105000,"bref":["La mer de Savu est une mer intérieure en forme de triangle renversé située en Asie du Sud-Est, dans les archipels orientaux (ou Insulinde). Elle s'étend entre les îles Banta et Komodo au nord-ouest, Florès au centre nord, puis Adonara, Kawula, Lembata, Pantar et Alor (en partie, jusqu'au méridien 125° de longitude est) au nord-est, l'île Sumba au sud-ouest, les îles Raijua, Savu et Dana au sud, enfin Rote et Timor au sud-est."],"src":"https://fr.vikidia.org/wiki/Mer_de_Savu","sw":"v","q":"Q193465","pays":["TL","ID"],"c":["asie"]},"mer-de-siberie-orientale":{"n":"mer de Sibérie orientale","t":"mer","km2":987000,"bref":["La mer de Sibérie orientale (en russe : Восточно-Сибирское море) est une mer bordière de l'océan Arctique. Elle est comprise entre la côte de Sibérie au sud, l'archipel de Nouvelle-Sibérie au nord-ouest qui la sépare de la mer des Laptev et l'île Wrangel à l'est qui la sépare de la mer des Tchouktches."],"src":"https://fr.wikipedia.org/wiki/Mer_de_Sib%C3%A9rie_orientale","sw":"w","q":"Q163434","pays":["RU"],"c":["asie","europe"]},"mer-de-somov":{"n":"mer de Somov","t":"mer","km2":1150000,"bref":["La mer de Somov est une mer de l’océan Pacifique située près de l'Antarctique, approximativement entre 150° et 170° Est, au nord des côtes de la terre de Oates. À l'ouest se trouve la mer d'Urville, et à l'est la mer de Ross. Les îles Balleny sont situées à 240 km de la côte de la mer de Somov.","La mer a été nommée en l'honneur de l'océanographe et explorateur polaire russe Mikhaïl Somov.","Portail du monde maritime Portail de l’Antarctique"],"src":"https://fr.wikipedia.org/wiki/Mer_de_Somov","sw":"w","q":"Q1404920"},"mer-de-soulou":{"n":"mer de Soulou","t":"mer","km2":348000,"bref":["La mer de Sulu ou mer de Jolo est une mer intérieure de l'Insulinde située au sud-ouest des Philippines et au nord-est de la Malaisie orientale. Elle couvre une superficie d'environ 348 000 km2. Au nord-ouest, elle est séparée de la mer de Chine méridionale par l'île de Palawan et au sud-est de la mer de Célèbes par l'archipel de Sulu. Bornéo est située au sud-ouest tandis que Mindoro et l'archipel des Visayas sont au nord-est.","Avec la mer de Célèbes au sud, elle est le lieu d'un intense trafic d'êtres humains, d'armes et de drogue. Des coopérations transfrontalières entre la Malaisie et les Philippines ont pour objectif d'atténuer ces trafics, mais aussi de conservation d'une biodiversité et de massifs coralliens importants. Les forces américaines surnomment cette zone maritime T3 pour « Terrorist Transit Triangle ». Plusieurs groupes terroristes sont au cœur d'un vaste réseau de trafics comme les islamistes séparatistes des Philippines à culture dominante catholique depuis l'arrivée des Espagnols à la période moderne, puis des Américains au XXe siècle."],"src":"https://fr.wikipedia.org/wiki/Mer_de_Sulu","sw":"w","q":"Q160194","pays":["PH"],"c":["asie"]},"mer-de-tasman":{"n":"mer de Tasman","t":"mer","km2":2300000,"bref":["La mer de Tasman est une mer marginale de l'océan Pacifique Sud. Elle baigne le Sud-Est de l'Australie et la Nouvelle-Zélande. Elle doit son nom à Abel Tasman (1603-1659), navigateur néerlandais."],"src":"https://fr.vikidia.org/wiki/Mer_de_Tasman","sw":"v","q":"Q33254","pays":["AU","NZ"],"c":["oceanie"]},"mer-de-timor":{"n":"mer de Timor","t":"mer","km2":610000,"bref":["La mer de Timor (Laut Timor en indonésien, Mar Timor en portugais) est une mer de l'Insulinde séparant principalement l'île indonésienne de Roti et l'île de Timor du Nord de l'Australie. Du côté australien, elle abrite plusieurs golfes : de Scambridge, Joseph-Bonaparte, du Beagle et Van Diemen. À l'ouest la mer de Timor débouche sur l'océan Indien et à l'est sur la mer d'Arafura. Elle a une surface de 610 000 km2 et sa largeur varie de 346 km à l'est à 484 km à l'ouest. Dans sa partie nord se trouve la fosse de Timor (Timor Trough) qui atteint 3 310 m de profondeur."],"src":"https://fr.vikidia.org/wiki/Mer_de_Timor","sw":"v","q":"Q131418","pays":["ID","TL","AU"],"c":["asie","oceanie"]},"mer-des-caraibes":{"n":"mer des Caraïbes","t":"mer","km2":2754000,"bref":["La mer des Caraïbes, ou mer des Antilles, est une mer bordière de l'océan Atlantique, située entre les Grandes Antilles, les Petites Antilles, l'Amérique du Sud et l'Amérique centrale. Elle s'étend sur 2 640 000 km2, une superficie comparable à la Méditerranée. Elle comporte trois divisions subalternes :","le golfe de Darién, entre la côte nord-est du Panamá et la côte nord-ouest du Venezuela ;","Le golfe du Venezuela, au nord de la lagune de Maracaïbo ;","le golfe du Honduras, entre la côte est du Belize, la côte nord-est du Guatemala et la côte nord du Honduras."],"src":"https://fr.vikidia.org/wiki/Mer_des_Cara%C3%AFbes","sw":"v","q":"Q1247","pays":["US","DO","PA","CO","JM","HT","GB","MX","BZ","CU","GT","HN","NI","CR","VE","PR","GD","LC","FR","DM","KN"],"c":["amerique-nord","amerique-sud","europe"]},"mer-des-cosmonautes":{"n":"mer des Cosmonautes","t":"mer","km2":699000,"bref":["La mer des Cosmonautes (en russe : Море Космонавтов) est une mer de l'océan Austral, au sud de l’océan Indien, située près de l'Antarctique. Elle est située entre la mer de Riiser Larsen (à l'ouest) et la mer de l'Entente (à l'est). Au sud, elle baigne la côte de la terre d'Enderby.","Elle a été baptisée ainsi en 1962 par l'Expédition antarctique soviétique en hommage aux cosmonautes du programme spatial soviétique."],"src":"https://fr.wikipedia.org/wiki/Mer_des_Cosmonautes","sw":"w","q":"Q1509546"},"mer-des-moluques":{"n":"mer des Moluques","t":"mer","km2":200000,"bref":["La mer des Moluques est une mer marginale de l'Est de l'Indonésie. C'est une mer plutôt réduite, sa superficie n'étant que de 200 000 km2. Elle n'occupe en effet que la partie la plus septentrionale du vaste archipel des Moluques."],"src":"https://fr.vikidia.org/wiki/Mer_des_Moluques","sw":"v","q":"Q185291","pays":["ID"],"c":["asie"]},"mer-des-philippines":{"n":"mer des Philippines","t":"mer","km2":5000000,"bref":["La mer des Philippines est une mer marginale bordière de l'océan Pacifique Nord.","Elle est située entre le Japon méridional au nord (Sud de Honshū, Shikoku et Kyūshū), l'archipel Nansei au nord-ouest, Taïwan à l'ouest, les côtes ouest et sud-ouest des Philippines au sud-ouest, l'île indonésienne de Morotai au sud, Palaos, Yap (Micronésie) et Guam au sud-est, les îles Mariannes du Nord à l'est, enfin l'archipel Nanpo au nord-est. La mer des Philippines est la plus grande de la Terre avec 5 695 000 km2."],"src":"https://fr.vikidia.org/wiki/Mer_des_Philippines","sw":"v","q":"Q159183","pays":["FM","US","ID","JP","PW","PH","TW"],"c":["oceanie","amerique-nord","asie"]},"mer-des-salomon":{"n":"mer des Salomon","t":"mer","km2":720000,"bref":["La mer des Salomon est une mer bordière située dans l'Ouest de l'océan Pacifique. Elle est bordée par la Nouvelle-Guinée à l'ouest, par la Nouvelle-Bretagne au nord-ouest, par les îles Salomon au nord-est et à l'est, par les bords d'Uluma Reef, de Lawik Reef (au large de Sudest Island connue aussi sous le nom de Tagula Island) et Rennell Island au sud."],"src":"https://fr.vikidia.org/wiki/Mer_des_Salomon","sw":"v","q":"Q199479","pays":["SB","PG"],"c":["oceanie"]},"mer-des-sargasses":{"n":"mer des Sargasses","t":"mer","bref":["La mer des Sargasses se situe dans l'Océan Atlantique Nord. Sa particularité est qu'elle n'a aucun pays côtier contrairement à toutes les autres mers. Elle a été appelée mer des Sargasses car il y a des algues qui s'appellent sargasses qui y flottent. C'est Christophe Colomb qui a découvert la mer des Sargasses. Elle joue un rôle très important dans la migration des anguilles européennes et américaines. Autrefois les marins redoutaient la mer des Sargasses car cette étendue d'algues les empêchaient d'avancer correctement."],"src":"https://fr.vikidia.org/wiki/Mer_des_Sargasses","sw":"v","q":"Q169274"},"mer-des-tchouktches":{"n":"mer des Tchouktches","t":"mer","km2":582000,"bref":["La mer des Tchouktches est une mer épicontinentale de l'océan Arctique située entre le nord-est de la Russie et le nord-ouest de l'Alaska. Elle inclut à l'ouest le détroit de Long. La mer a une superficie de 582 000 km2."],"src":"https://fr.vikidia.org/wiki/Mer_des_Tchouktches","sw":"v","q":"Q159252","pays":["RU","US"],"c":["asie","europe","amerique-nord"]},"mer-du-groenland":{"n":"mer du Groenland","t":"mer","km2":1205000,"bref":["La mer du Groenland est une mer bordière de l'océan Arctique, située entre l'Islande, le Groenland, Jan Mayen et le Spitzberg. Sa superficie est de 1 205 000 km2. Sa profondeur moyenne\test de 1 450 m et sa profondeur maximale de 4 800 m.","Elle communique avec la mer de Norvège au sud-est et avec l'océan Atlantique au sud-ouest. Au nord, elle débouche sur l'océan Arctique. Elle compte de nombreux microrganismes et de poissons tels que la morue, le hareng ou le saumon."],"src":"https://fr.vikidia.org/wiki/Mer_du_Groenland","sw":"v","q":"Q132868","pays":["GL","NO"],"c":["amerique-nord","europe"]},"mer-du-labrador":{"n":"mer du Labrador","t":"mer","km2":841000,"bref":["La mer du Labrador (56° 24′ N, 50° 56′ O) est une partie","de l'océan Atlantique située entre la péninsule du Labrador, Terre-Neuve, (Canada) et le Groenland. Sa profondeur en son milieu peut atteindre 3 000 mètres et elle est entourée de côtes continentales au sud-ouest, nord-ouest et nord-est. Elle est reliée au nord au détroit de Davis.","La mer du Labrador présente la particularité d'être un espace maritime incorporé à un océan, et non une mer bordière distincte, comme sa voisine, le golfe du Saint-Laurent. Tout en possédant ses propres limites, elle est comprise dans les limites de l'océan Atlantique.","La mer du Labrador s'est constituée par un écartement progressif des fonds marins, le processus a débuté il y a environ 61 millions d'années pour cesser il y a 40 millions d'années. Pendant la période glaciaire, la couche nord-américaine déversa régulièrement de nombreux icebergs dans la mer du Labrador. Les roches prises au piège de ces icebergs se sont déposées sur le fond de la mer où elles forment une couche glaciaire erratique."],"src":"https://fr.wikipedia.org/wiki/Mer_du_Labrador","sw":"w","q":"Q184189","pays":["CA","GL"],"c":["amerique-nord"]},"mer-du-nord":{"n":"mer du Nord","t":"mer","km2":570000,"bref":["La mer du Nord est une mer du Nord-Ouest de l'Europe. Elle borde la France, la Grande-Bretagne, la Norvège, le Danemark, l'Allemagne, les Pays-Bas et la Belgique. La mer du Nord communique avec la Manche par le détroit du pas de Calais. Elle est séparée de la mer Baltique par le Skagerrak, un golfe-détroit situé entre la Norvège, la Suède et le Danemark, et par le Cattegat, un ensemble de détroits danois. Ses limites avec l'océan Atlantique sont à hauteur des îles Orcades et des îles Shetland. Sur les estuaires et deltas qui y débouchent se trouvent la plupart des grands ports européens (Rotterdam, Londres, Anvers, Hambourg...). C'est l'une des mers les plus fréquentées du monde par les marines de commerce. Le sous-sol recèle de riches gisements d'hydrocarbures."],"src":"https://fr.vikidia.org/wiki/Mer_du_Nord","sw":"v","q":"Q1693","pays":["NO","DK","DE","BE","FR","GB"],"c":["europe"]},"mer-egee":{"n":"mer Égée","t":"mer","km2":214000,"bref":["La mer Égée désigne la partie orientale de la Méditerranée comprise entre la Grèce à l'ouest et la Turquie à l'est. Elle est reliée à la mer Noire par la mer de Marmara et ses détroits : les Dardanelles et le Bosphore. La mer Égée comprend de grandes îles et de nombreux archipels.","Son nom lui vient d'Égée, roi légendaire d'Athènes qui s'est jeté à l'eau, croyant son fils Thésée mort.","La mer Égée a été le cadre du développement de la civilisation égéenne du deuxième millénaire av. J-C, c'est-à-dire de la civilisation mycénienne et de celle de Troie."],"src":"https://fr.vikidia.org/wiki/Mer_%C3%89g%C3%A9e","sw":"v","q":"Q34575","pays":["GR","TR"],"c":["europe","asie"]},"mer-jaune":{"n":"mer Jaune","t":"mer","km2":380000,"bref":["La mer Jaune est une mer épicontinentale entourée à l'ouest et au nord-ouest par la Chine, au nord-est par la Corée du Nord, à l'est par la Corée du Sud et au sud par la mer de Chine orientale, au-delà du parallèle 33°17' N. Sa superficie totale est de 380 000 km2, le Bohai inclus.","De l'estuaire de la rivière Dapu, au fond du Bohai, à la ville de Gyema-Ri, dans la province sud-coréenne de Jeollanam-do, on compte 784 km, une des plus grandes dimensions de cet espace maritime."],"src":"https://fr.vikidia.org/wiki/Mer_Jaune","sw":"v","q":"Q37960","pays":["CN","KP","KR"],"c":["asie"]},"mer-rouge":{"n":"mer Rouge","t":"mer","km2":445816,"bref":["La mer Rouge (arabe : البحر الأحمر al-Bahr al-Ahmar, copte : ⲫⲓⲟⲙ ⲛ̀ϩⲁϩ Phiom enhah ou ⲫⲓⲟⲙ ⲛ̀ϣⲁⲣⲓ Phiom nšari, hébreu : ים סוף Yam Suf, araméen : ܝܡܐ ܣܘܡܩܐ Yammāʾ Summāqā, tigrinya : ቀይሕ ባሕሪ Qeyih Bahri, somali : Badda Cas 𐒁𐒖𐒆𐒆𐒖 𐒋𐒖𐒈.) est une mer intercontinentale bordière de l'océan Indien et située entre l'Afrique du Nord et l'Asie de l'Ouest. Elle a une superficie d'environ 450 000 km2. C'est une mer d'une grande importance stratégique et commerciale qui permet aux navigateurs en provenance de la mer Méditerranée et à destination de l'océan Indien (ou vice-versa) d'éviter le contournement de l'Afrique par le cap de Bonne Espérance en passant par le canal de Suez au nord-ouest."],"src":"https://fr.wikipedia.org/wiki/Mer_Rouge","sw":"w","q":"Q23406","pays":["EG","SA","SD","DJ","ER","YE","IL","JO"],"c":["afrique","asie"]},"mer-tyrrhenienne":{"n":"mer Tyrrhénienne","t":"mer","km2":275000,"bref":["La mer Tyrrhénienne est le nom donné à la partie de la mer Méditerranée comprise entre la côte italienne depuis La Spezia au nord-est, la Corse et la Sardaigne à l'ouest et la Sicile au sud-est.","C'est une mer relativement profonde (sa profondeur moyenne est de 2000 mètres et sa profondeur maximale est de 4600 mètres (entre la Sardaigne et l'Italie). Il y a plusieurs groupes d'îles : au nord l'île d'Elbe, l'ile de Montecristo et l'île de Pianosa, à l'est les îles Ponziane, Ischia et Capri, au sud-est les îles Éoliennes (Lipari, Stromboli, Vulcano...)","Ses côtes sont le plus souvent rocheuses, très élevées (sauf dans le Latium et en Campanie en Italie).","La mer Tyrrhénienne s'est formée au Pliocène, par la rotation de la micro plaque (Italie-mer Adriatique) de l'écorce terrestre en direction du nord-est. Le volcanisme ancien et actuel y est très actif (Stromboli, Vulcano)."],"src":"https://fr.vikidia.org/wiki/Mer_Tyrrh%C3%A9nienne","sw":"v","q":"Q38882","pays":["FR","IT"],"c":["europe"]}},
"fleuves":{"aar":{"n":"Aar","t":"rivière","km":295,"bassin":17800,"debit":560,"src2":"Aar Glaciers","emb":"Rhin","bref":["L'Aar est une rivière de la Suisse. C'est un affluent du Rhin. Il mesure 295 km.","L'Aar a sa source dans les Alpes bernoises à 2 310 m d'altitude. Il traverse les lacs de Brienz et de Thoune."],"src":"https://fr.vikidia.org/wiki/Aar","sw":"v","q":"Q1675","pays":["CH"],"c":["europe"]},"adige":{"n":"Adige","t":"fleuve","km":410,"bassin":14700,"debit":266,"src2":"col de Resia","emb":"mer Adriatique","bref":["L'Adige (allemand Etsch, ladin Adesc, latin Athesis, frioulan Adiç, trentinois Ades, vénitien Àdexe et romanche : ) est un fleuve d’Italie qui naît dans les Alpes, aux confins de la Suisse et de l’Autriche, et se jette dans la mer Adriatique.","Avec ses 410 km, c'est le deuxième fleuve italien après le Pô, mais également le troisième pour la taille du bassin versant après le Pô et le Tibre et le quatrième pour le débit après le Pô, le Tessin et le Tibre, avec un débit annuel moyen de 235m3/s à son embouchure.","Il traverse les villes de Trente, Vérone, Legnago, Cavarzere et longe Merano, Bolzano, Rovereto et Rovigo. Il traverse les régions du Trentin-Haut-Adige et de la Vénétie. La vallée dans laquelle il coule prend différents noms : val Venosta entre la source et Mérano, la vallée de l'Adige entre Mérano et Trente, Vallagarina entre Trente et Verone, puis la plaine du Pô entre Vérone et l'embouchure."],"src":"https://fr.wikipedia.org/wiki/Adige","sw":"w","q":"Q13696","pays":["IT"],"c":["europe"]},"aldan":{"n":"Aldan","t":"rivière","km":2273,"bassin":729000,"debit":5060,"src2":"Monts Stanovoï","emb":"Léna","bref":["L'Aldan (en russe : Алдан) est une rivière longue de 2 273 km, située en Sibérie, en Russie d'Asie. C'est un des principaux affluents de la Léna. Aldan veut dire en langue iakoute : « qui charrie de l'or »."],"src":"https://fr.wikipedia.org/wiki/Aldan_(rivi%C3%A8re)","sw":"w","q":"Q191832","pays":["RU"],"c":["asie","europe"]},"amazone":{"n":"Amazone","t":"fleuve","km":6400,"bassin":7050000,"debit":209000,"src2":"rivière Marañón","emb":"océan Atlantique","bref":["L'Amazone est l'un des deux plus longs fleuves sur Terre (environ 7 000 km), l'autre étant le Nil en Afrique. Il se trouve en Amérique du Sud : il prend sa source dans la cordillère des Andes, près de la côte ouest, au Pérou, et se jette dans l'océan Atlantique, dans le Nord du Brésil. Son nom lui a été donné par l'explorateur espagnol Orellana, qui vers 1540, a combattu sur les rives du fleuve, des Indiens aux cheveux longs (qu'il a assimilé aux Amazones, guerrières de l'Antiquité grecque)."],"src":"https://fr.vikidia.org/wiki/Amazone_(fleuve)","sw":"v","q":"Q3783","pays":["PE","CO","BR"],"c":["amerique-sud"]},"amou-daria":{"n":"Amou-Daria","t":"rivière","km":2620,"bassin":309000,"debit":1400,"src2":"Pamir","emb":"Grande Aral","bref":["L'Amou-Daria est un fleuve d'Asie centrale d'une longueur de 1 415 kilomètres. Il commence au confluent du Vakhch et du Panj, deux cours d'eau ayant pris naissance dans la chaîne du Pamir. Cependant, on est en droit de considérer le parcours effectué depuis les sources réelles, autrement dit celles du Panj. Ces sources (37° 56′ 18″ N 71° 34′ 53″ E / 37.938345, 71.581382) sont situées en Afghanistan, pratiquement sur la frontière","avec le Tadjikistan. On obtient alors un total de 2 540 kilomètres pour le parcours Panj/Amou-Daria. C'est donc ce kilométrage qu'il convient de retenir. Le fleuve est endoréique car il n'atteint plus la mer d'Aral."],"src":"https://fr.vikidia.org/wiki/Amou-Daria","sw":"v","q":"Q8493","pays":["TM","TJ","AF","UZ"],"c":["asie"]},"amour":{"n":"Amour","t":"fleuve","km":2824,"bassin":1855000,"debit":12800,"src2":"Onon","emb":"mer d'Okhotsk","bref":["L’Amour (en russe : Амур ; en nanaï : Мангбо ou Дāи Маңбо ; en mandchou : , ᠰᠠᡥᠠᠯᡳᠶᠠᠨ ᡠᠯᠠ et en chinois : 黑龙江 ou 黑龍江) est un fleuve sino-russe prenant sa source en Chine. Le nom chinois, écrit en caractères latins est : Hēilóngjiāng (« fleuve du dragon noir »)."],"src":"https://fr.vikidia.org/wiki/Amour_(fleuve)","sw":"v","q":"Q6862","pays":["RU","CN"],"c":["asie","europe"]},"angara":{"n":"Angara","t":"rivière","km":1779,"bassin":1039000,"debit":4518,"src2":"lac Baïkal","emb":"Ienisseï","bref":["L'Angara (en russe : Ангара) est une rivière de Sibérie, en Russie. Elle est l'unique émissaire du lac Baïkal et coule dans l'oblast d'Irkoutsk, puis dans le kraï de Krasnoïarsk, en Sibérie orientale. C'est un affluent de l'Ienisseï en rive droite.","L'Angara est la seule rivière issue du lac Baïkal alors que celui-ci reçoit 336 cours d'eau. En aval de son confluent avec la rivière Ilim, l'Angara était autrefois connue sous le nom de Toungouska Supérieure (en russe : Верхняя Тунгуска, Verkhniaïa Toungouska)."],"src":"https://fr.wikipedia.org/wiki/Angara","sw":"w","q":"Q162737","pays":["RU"],"c":["asie","europe"]},"araxe":{"n":"Araxe","t":"rivière","km":1072,"bassin":102000,"debit":285,"src2":"monts de Bingöl","emb":"Koura","bref":["L'Araxe (Aras, Araks, Yeraskh, Arax, Araxes, ou Araz ; en arménien : Արաքս mais aussi Երասխ / Eraskh ; en persan : ارس ; en azéri : Araz) est une rivière prenant sa source sur le haut-plateau arménien, dans l'est de la Turquie, et qui se jette dans la Koura, à 121 km de son embouchure sur la mer Caspienne."],"src":"https://fr.wikipedia.org/wiki/Araxe","sw":"w","q":"Q179751","pays":["IR","TR","AM","AZ"],"c":["asie","europe"]},"brahmapoutre":{"n":"Brahmapoutre","t":"rivière","km":2900,"bassin":651334,"debit":19500,"emb":"Gange","bref":["Le Brahmapoutre ou en Chine Yarlung Zangbo ou au Bangladesh Jamuna, est un fleuve d'Asie d'une longueur de 2896 kilomètres. Il traverse trois pays : la Chine, l'Inde et le Bangladesh."],"src":"https://fr.vikidia.org/wiki/Brahmapoutre","sw":"v","q":"Q45403","pays":["IN","CN","BD","NP"],"c":["asie"]},"chao-phraya":{"n":"Chao Phraya","t":"fleuve","km":372,"bassin":15000,"emb":"golfe de Thaïlande","bref":["Le Chao Phraya (thaï : แม่น้ำเจ้าพระยา), ou Maenam Chao Phraya, est le plus important fleuve de Thaïlande après le Mékong et la Salouen. C'est aussi le seul de ces trois fleuves à couler entièrement dans le pays et il constitue encore aujourd'hui un axe majeur de transport et de commerce. Il se forme au confluent des rivières Ping et Nan et s'écoule vers le sud sur 372 km avant de se jeter dans le golfe de Thaïlande. La vallée du Chao Phraya est une grande région productrice de riz.","Le mot Maenam signifie « rivière » en thaï : ce mot est formé de deux éléments : mae (thaï : แม่) signifiant « mère » et nam (thaï: น้ำ)« eau ». Chao Phraya est le titre de noblesse thaïlandais le plus élevé.","Non loin de son embouchure, le Chao Phraya traverse Bangkok, ville où jadis avaient lieu de fameux marchés flottants. De nos jours, on ne trouve que quelques marchés flottants, la plupart en dehors de la capitale : le plus célèbre est celui de Damnoen Saduak à 80 km à l'ouest de Bangkok."],"src":"https://fr.wikipedia.org/wiki/Chao_Phraya","sw":"w","q":"Q118850","pays":["TH"],"c":["asie"]},"chatt-el-arab":{"n":"Chatt-el-Arab","t":"fleuve","km":200,"bassin":884000,"debit":1500,"src2":"Tigre","emb":"golfe Persique","bref":["Le Chatt-el-Arab (arabe : شط العرب) ou Chott-el-Arab (« La rive des Arabes ») ou Arvandroud (appelée اروندرود : arvandrūd en persan) est le principal chenal du delta commun du Tigre et de l'Euphrate. Il débouche sur le golfe Persique après un parcours de 200 km. Sur la partie aval de son parcours, il constitue la frontière entre l'Irak et l'Iran."],"src":"https://fr.wikipedia.org/wiki/Chatt-el-Arab","sw":"w","q":"Q166966","pays":["IR","IQ"],"c":["asie"]},"chenab":{"n":"Chenab","t":"rivière","km":1974,"bassin":138000,"src2":"Chandra","emb":"Panjnad","bref":["La Chenab (pendjabi : ਚਨਾਬ, canāb, ourdou : چناب, hindi : चनाब, littéralement : « Lune (Chen) Rivière (ab) ») est une rivière formée par la confluence de la Chandra et de la Bhaga à Tandi, dans l'Himalaya, dans le district de Lahul et Spiti dans l'Himachal Pradesh (Inde)."],"src":"https://fr.wikipedia.org/wiki/Chenab","sw":"w","q":"Q216875","pays":["IN","PK"],"c":["asie"]},"colorado":{"n":"Colorado","t":"fleuve","km":2334,"bassin":637137,"debit":640,"src2":"La Poudre Pass","emb":"golfe de Californie","bref":["Le Colorado est un fleuve du Sud-Ouest des États-Unis. Il prend sa source dans les montagnes Rocheuses, au nord de l'État du Colorado, et se jette dans le golfe de Californie, au Mexique.","Sa longueur est de 2 334 km. Il traverse les États du Colorado, de l'Utah et de l'Arizona.","Il marque la limite entre les États du Nevada et de l'Arizona, puis entre la Californie et l'Arizona.","Les lieux touristiques les plus connus sur le cours du Colorado sont le Grand Canyon et le barrage Hoover, construit entre 1931 et 1937."],"src":"https://fr.vikidia.org/wiki/Colorado_(fleuve)","sw":"v","q":"Q1265","pays":["US","MX"],"c":["amerique-nord"]},"congo":{"n":"Congo","t":"fleuve","km":4700,"bassin":401450000,"debit":41800,"src2":"chutes Boyoma","emb":"océan Atlantique","bref":["Le Congo est un fleuve d'Afrique centrale prenant sa source sur les hauts plateaux à la limite de l'Afrique australe, drainant de nombreux pays (dont majoritairement la république démocratique du Congo) et se jetant dans l'océan Atlantique. Il sert de frontière entre la république démocratique du Congo, la république du Congo et l'Angola. Son cours supérieur est appelé Lwalaba ou Lualaba, et entre les années 1970 et 1990 (zaïrianisation), la totalité du fleuve était appelé Zaïre à l'époque du Zaïre.","Avec ses 4 700 kilomètres de longueur, il est le huitième plus long fleuve du monde mais le second après l'Amazone pour son débit de 80 832 m3/s au maximum. Son bassin versant, d'une superficie de 3 680 000 km2, est le deuxième du monde. Sous réserve des vérifications nécessaires, des relevés bathymétriques par sonar effectués en 2008 pourraient en faire le fleuve le plus profond au monde, avec une profondeur dépassant 220 mètres sous forme de canyons immergés ; ses eaux abritent même une faune typiquement abyssale, parfois rejetée agonisante à sa surface en raison d'accidents de décompression brutale provoqués par la force des courants."],"src":"https://fr.wikipedia.org/wiki/Congo_(fleuve)","sw":"w","q":"Q3503","pays":["AO","CD","CG","ZM"],"c":["afrique"]},"danube":{"n":"Danube","t":"fleuve","km":2850,"bassin":801463,"debit":5433,"src2":"Brigach","emb":"mer Noire","bref":["Le Danube est le deuxième cours d'eau d’Europe par la longueur et le plus long de l’Union européenne. Il a servi de frontière à de grands empires et a été une importante voie commerciale. D'une longueur de 2 850 kilomètres, le fleuve forme un bassin drainant de 817 000 kilomètres carrés."],"src":"https://fr.vikidia.org/wiki/Danube","sw":"v","q":"Q1653","pays":["DE","AT","SK","HU","HR","RS","RO","BG","MD"],"c":["europe"]},"darling":{"n":"Darling","t":"rivière","km":1472,"bassin":710000,"debit":100,"emb":"Murray","bref":["Le Darling est le troisième plus long cours d'eau d'Australie, s'étendant sur 1 570 km depuis le nord de la Nouvelle-Galles du Sud jusqu'à Wentworth (toujours dans le même État), où il rejoint le Murray. Certains géographes considèrent le Darling et la partie basse du Murray comme un seul et même fleuve, long de 3 000 km."],"src":"https://fr.wikipedia.org/wiki/Darling_(rivi%C3%A8re)","sw":"w","q":"Q181482","pays":["AU"],"c":["oceanie"]},"daugava":{"n":"Daugava","t":"fleuve","km":1020,"bassin":87900,"debit":678,"src2":"Collines de Valdaï","emb":"golfe de Riga","bref":["La Daugava ou Dvina occidentale (letton : Daugava ; russe : Западная Двина, Zapadnaïa Dvina ; biélorusse : Заходняя Дзвiна, Zakhodniaïa Dzvina ; polonais : Dźwina ; allemand : Düna ; estonien : Väina ; finnois : Väinäjoki) est un fleuve de 1 020 km qui coule en Russie, en Biélorussie et en Lettonie."],"src":"https://fr.wikipedia.org/wiki/Daugava","sw":"w","q":"Q8197","pays":["BY","RU","LV"],"c":["europe","asie"]},"dniepr":{"n":"Dniepr","t":"rivière","km":2285,"bassin":503500,"debit":1670,"src2":"Collines de Valdaï","emb":"liman du Dniepr","bref":["Le Dniepr (en russe : Днепр / Dniepr ; en ukrainien : Днiпро / Dnipro) qui prend sa source en Russie et continue son cours en Biélorussie et en Ukraine, avant de se jeter dans la mer Noire. Il s'étend sur 2 290 km, ce qui le met à la troisième place des fleuves d'Europe pour la longueur.","Le Dniepr prend sa source en Russie centrale, dans les collines de Valdaï, à 220 m d'altitude. Il parcourt 485 km en Russie, puis 595 km en Biélorussie et enfin 1 095 km en Ukraine.","Il arrose des villes importantes :","en Biélorussie : Orcha et Moguilev ;","en Ukraine : Kiev, Tcherkassy, Krementchouk, Dnipropetrovsk, Zaporijia, Nikopol et Kherson.","N.B. : Ne pas confondre avec le Dniestr, un autre fleuve, à l'Ouest de l'Ukraine."],"src":"https://fr.vikidia.org/wiki/Dniepr","sw":"v","q":"Q40855","pays":["RU","BY","UA"],"c":["asie","europe"]},"dniestr":{"n":"Dniestr","t":"rivière","km":1352,"bassin":72100,"debit":310,"src2":"Carpates ukrainiennes","emb":"liman du Dniestr","bref":["Le Dniestr (nom russe Днестр) ou Nistru (nom roumain) ou Dnister (nom ukrainien Дністер) est un fleuve d'Europe de l'Est long de 1 362 km, issu des Carpates ukrainiennes, dans les Beskides orientales, en Ukraine occidentale, et aboutissant à la mer Noire en Ukraine méridionale. Il coule d'abord vers le nord-est puis vers le sud-est, passe à Sambir, Halytch, Khotyn et Mohyliv-Podilskyï, Soroca, Bender-Tighina, Tiraspol, Ovidiopol et Bilhorod-Dnistrovskyï, avant de déboucher dans le liman du Dniestr, au sud-ouest d'Odessa. Les dictionnaires français ont adopté le nom russe. Dans l'antiquité il était nommé en grec et latin Tyras et en scythe Danastris.","Après avoir été, de 1359 à 1812, la frontière orientale de la principauté de Moldavie qui y a élevé les forteresses de Hotin, Movilău, Soroca, Tighina et Cetatea Albă face aux razzias des Tatars, il est devenu au XVIIIe siècle un fleuve austro-hongrois en amont et au XIXe siècle un fleuve russe en aval, puis entièrement soviétique de 1945 à 1991. Depuis, il fait partiellement office de frontière entre l'Ukraine et la Moldavie, et, à l'intérieur de celle-ci, entre la zone sous contrôle du gouvernement (rive droite), et la zone sous contrôle russe (rive gauche)."],"src":"https://fr.wikipedia.org/wiki/Dniestr","sw":"w","q":"Q131210","pays":["UA","MD"],"c":["europe"]},"don":{"n":"Don","t":"fleuve","km":1870,"bassin":422000,"debit":935,"src2":"Plateau central de Russie","emb":"mer d'Azov","bref":["Le Don (en russe : Дон) est un fleuve de Russie, long de 1 870 km.","Il prend sa source près de Toula, au sud de Moscou, et se jette dans la Mer d'Azov.","C'est l'un des principaux fleuves de Russie et l'un des plus grands d'Europe."],"src":"https://fr.vikidia.org/wiki/Don_(fleuve)","sw":"v","q":"Q1229","pays":["RU"],"c":["asie","europe"]},"douro":{"n":"Douro","t":"fleuve","km":897,"bassin":97290,"debit":675,"src2":"Picos de Urbión","emb":"océan Atlantique","bref":["Le Douro (nom portugais), ou Duero (nom espagnol), est un fleuve du nord-ouest de la péninsule Ibérique, d'une longueur de presque 900 km."],"src":"https://fr.vikidia.org/wiki/Douro","sw":"v","q":"Q14299","pays":["ES","PT"],"c":["europe"]},"drave":{"n":"Drave","t":"rivière","km":720,"bassin":40400,"debit":620,"src2":"San Candido","emb":"Danube","bref":["La Drave (Drau en allemand, Drava en italien, slovène et croate, Dráva en hongrois) est une rivière d'Europe centrale, dans le bassin du moyen Danube, second affluent (droit) du Danube par sa longueur."],"src":"https://fr.wikipedia.org/wiki/Drave_(cours_d'eau)","sw":"w","q":"Q171009","pays":["IT","HR","AT","SI","HU"],"c":["europe"]},"dvina-septentrionale":{"n":"Dvina septentrionale","t":"fleuve","km":744,"bassin":357000,"debit":3490,"src2":"Ioug","emb":"baie de la Dvina","bref":["La Dvina septentrionale ou Dvina du Nord (en russe : Северная Двина, Severnaïa Dvina) est un fleuve de 744 km qui coule dans le nord de la Russie d'Europe sur les territoires des oblast de Vologda et d'Arkhangelsk. Elle se jette dans la baie de la Dvina (mer Blanche) après avoir formé un delta. Le bassin de la Dvina septentrionale a une superficie de 357 052 km2."],"src":"https://fr.wikipedia.org/wiki/Dvina_septentrionale","sw":"w","q":"Q8187","pays":["RU"],"c":["asie","europe"]},"ebre":{"n":"Èbre","t":"fleuve","km":910,"bassin":86800,"debit":426,"src2":"Fontibre","emb":"mer Méditerranée","bref":["L'Èbre (Ebro en espagnol) est un fleuve espagnol, qui mesure 928 km de long et prend sa source à Peñalabra à 1980 m d'altitude. Il se jette dans la mer Méditerranée en formant un delta peuplé de 50 000 habitants, et qui comprend un parc naturel, le parc naturel de l'Èbre, créé en 1983. C'est le plus puissant des fleuves espagnols."],"src":"https://fr.vikidia.org/wiki/%C3%88bre","sw":"v","q":"Q10965","pays":["ES"],"c":["europe"]},"elbe":{"n":"Elbe","t":"fleuve","km":1094,"bassin":148268,"debit":711,"src2":"monts des Géants","emb":"mer du Nord","bref":["L'Elbe (en allemand Elbe, en tchèque Labe) est un fleuve d'Europe centrale qui prend sa source en République tchèque dans les monts des Géants.","Passant ensuite en Allemagne, l'Elbe arrose les villes de Dresde et de Magdebourg, avant de se jeter dans la mer du Nord par un long estuaire d'une centaine de kilomètres au bord duquel se trouve Hambourg, premier port d'Allemagne.","La longueur de l'Elbe est de 1 091 kilomètres. Le fleuve est navigable sur la plus grande partie de son cours.","Ses principaux affluents sont la Moldau (qui arrose Prague), la Saale et l'Havel."],"src":"https://fr.vikidia.org/wiki/Elbe","sw":"v","q":"Q1644","pays":["CZ","DE"],"c":["europe"]},"escaut":{"n":"Escaut","t":"fleuve","km":355,"bassin":35500,"debit":120,"src2":"Source de l'Escaut","emb":"mer du Nord","bref":["L'Escaut (Schelde en néerlandais) est un fleuve du nord de la France, de la Belgique et des Pays-Bas. Il se jette dans la mer du Nord, par un delta appelé les « bouches de l'Escaut ». L'Escaut mesure 430 km (dont 180 km en France). Canalisé sur la plus grande partie de son cours et drainant, avec ses affluents, une grande partie de la Belgique, c'est un axe de communication d'une grande importance."],"src":"https://fr.vikidia.org/wiki/Escaut","sw":"v","q":"Q37620","pays":["FR","BE"],"c":["europe"]},"euphrate":{"n":"Euphrate","t":"rivière","km":2800,"bassin":673000,"debit":818,"emb":"Chatt-el-Arab","bref":["L'Euphrate est un fleuve d'Asie de 2 780 km de long. Avec le Tigre, il forme, dans sa partie basse, la Mésopotamie (du grec μέσος / mésos, « milieu » et ποταμός / potamós, « fleuve »), l'un des berceaux de la civilisation.","De type pluvio-nival, son débit est particulièrement irrégulier, puisque plus de la moitié de son flux s'écoule de mars à mai et que le débit peut tomber à 300 m3/s contre un débit moyen de 830 m3/s (à l'entrée en Syrie). En période de crue, il peut atteindre 5 200 m3/s pouvant provoquer de graves inondations. D'une année à l'autre, le volume d'eau varie fortement passant de 15 km3 lors de la sécheresse de 1958-1962 à 58 km3 en 1969.","Autre caractéristique, le débit diminue en traversant les zones sèches en raison de la forte évaporation, en particulier dans les lacs artificiels, et du pompage pour l'irrigation. Ainsi, alors que le volume moyen d'eau entrant en Syrie est de 28 km3, il tombe à 26 à la frontière irakienne malgré l'apport de trois affluents (1,75 km3) et n'est plus que de 14 à Nassiriya au sud de l'Irak (E. Vaumas, 1955)."],"src":"https://fr.wikipedia.org/wiki/Euphrate","sw":"w","q":"Q34589","pays":["TR","SY","IQ"],"c":["asie","europe"]},"fleuve-columbia":{"n":"fleuve Columbia","t":"fleuve","km":2000,"bassin":668217,"debit":7500,"src2":"lac Columbia","emb":"océan Pacifique","bref":["Le Columbia est un fleuve circulant du Canada aux États-Unis avant de se jeter dans l'océan Pacifique.","C'est le plus grand cours d'eau de la région Nord-Ouest Pacifique de l'Amérique du Nord, que ce soit par sa longueur totale, la taille du bassin versant ou son débit à l'embouchure. Il prend sa source dans les montagnes Rocheuses en Colombie-Britannique, au Canada, puis coule dans les États américains de Washington et de l'Oregon avant de se jeter dans l'océan Pacifique à la hauteur de la ville d'Astoria. Le fleuve mesure environ 2 000 kilomètres et son principal affluent est la Snake. Son bassin versant est d'environ 670 000 kilomètres carrés, soit un peu plus que la taille de la France, et s'étend sur sept États américains et une province canadienne."],"src":"https://fr.wikipedia.org/wiki/Columbia_(fleuve)","sw":"w","q":"Q2251","pays":["CA","US"],"c":["amerique-nord"]},"fleuve-fraser":{"n":"fleuve Fraser","t":"fleuve","km":2657,"bassin":233100,"debit":3475,"src2":"montagnes Rocheuses","emb":"détroit de Géorgie","bref":["Le fleuve Fraser (en anglais Fraser River, appelé communément en français « le Fraser ») est le plus grand fleuve de Colombie-Britannique (Canada). Long de 1 370 km, il prend sa source près du mont Robson dans les montagnes Rocheuses pour se jeter à Vancouver dans les eaux côtières de l'Alaska du Sud-Est et de la Colombie-Britannique (détroit de Géorgie)."],"src":"https://fr.wikipedia.org/wiki/Fleuve_Fraser","sw":"w","q":"Q269710","pays":["CA"],"c":["amerique-nord"]},"fleuve-jaune":{"n":"fleuve Jaune","t":"fleuve","km":5464,"bassin":752000,"debit":2571,"src2":"Kariqu","emb":"mer de Bohai","bref":["Le fleuve Jaune (chinois : 黃河 ; pinyin : Huáng hé), ou Huáng hé, est le deuxième plus long fleuve de Chine après le Yangtsé. Long de 5 464 kilomètres, il prend sa source dans le plateau tibétain et après avoir traversé les provinces de Gansu, Ningxia, Mongolie-Intérieure, Shaanxi, Shanxi, Henan et Shandong, se jette dans le golfe de Bohai en mer Jaune. Le bassin versant du fleuve d'une superficie de 752 443 km2 est caractérisé par un climat en grande partie semi-aride qui explique le débit modéré du fleuve à son embouchure (2 571 m3/s).","Le fleuve Jaune a joué un rôle crucial dans l'histoire de la Chine car la civilisation chinoise est née à la confluence du fleuve et de son affluent le Wei puis s'est développée le long de son cours. Caractérisé par des crues violentes et une forte charge sédimentaire arrachée au plateau de Lœss qu'il traverse sur son cours moyen, le fleuve Jaune a façonné et fertilisé la grande plaine de Chine du Nord. Sur son cours aval qui traverse celle-ci, les hommes ont depuis des millénaires tenté d'endiguer le fleuve et de limiter ses crues dévastatrices."],"src":"https://fr.wikipedia.org/wiki/Fleuve_Jaune","sw":"w","q":"Q7355","pays":["CN"],"c":["asie"]},"fleuve-mackenzie":{"n":"fleuve Mackenzie","t":"fleuve","km":1738,"bassin":1805200,"debit":10700,"src2":"Grand Lac des Esclaves","emb":"mer de Beaufort","bref":["Le fleuve Mackenzie (en anglais : Mackenzie River ; en esclave : Deh-Cho /tèh tʃʰò/, litt. « grande rivière » ; en inuvialuktun : Kuukpak /kuːk.pɑk/ litt. « grande rivière ») des Territoires du Nord-Ouest prend sa source dans le Grand lac des Esclaves et s'écoule vers la mer de Beaufort dans l'océan Arctique."],"src":"https://fr.wikipedia.org/wiki/Mackenzie_(fleuve)","sw":"w","q":"Q3411","pays":["CA"],"c":["amerique-nord"]},"fleuve-saint-laurent":{"n":"fleuve Saint-Laurent","t":"fleuve","km":1197,"bassin":1344200,"debit":10400,"src2":"lac Ontario","emb":"golfe du Saint-Laurent","bref":["Le fleuve Saint-Laurent est un cours d'eau situé en Amérique du Nord, entre les États-Unis (État de New York) et le Canada (provinces de l'Ontario puis du Québec). Il vient des Grands Lacs, et après avoir servi de frontière avec les États-Unis, coule entièrement au Canada at se jette dans le golfe du Saint-Laurent, une mer bordière de l'océan Atlantique. Tout le long de son parcours le fleuve va conserver à peu près la même direction, soit le nord-est. Le Saint-Laurent ne mesure que 1 197 kilomètres de long, mais le système qu'il constitue avec la rivière Saint-Louis (qui finit dans l'Ouest du lac Supérieur) et les Grands Lacs atteint 3 000 kilomètres. Son débit annuel moyen est de 12 000 mètres cubes par seconde. La superficie de son bassin drainant est de 1 610 000 kilomètres carrés."],"src":"https://fr.vikidia.org/wiki/Saint-Laurent_(fleuve)","sw":"v","q":"Q134750","pays":["CA","US"],"c":["amerique-nord"]},"fleuve-yukon":{"n":"Fleuve Yukon","t":"fleuve","km":3190,"bassin":832000,"debit":6428,"src2":"champ de glace Juneau","emb":"mer de Béring","bref":["Le Yukon est un important fleuve d'Amérique du Nord. Il prend sa source dans les monts Saint-Élie, une chaîne de montagnes située au Yukon et en Colombie-Britannique, une province de l'Ouest du Canada. Plus précisément, le fleuve naît au pied du glacier Llewellyn, lequel se déverse dans le lac Atlin (59° 08′ 04″ N 133° 59′ 29″ W / 59.134524, -133.991401). Le fleuve a donné son nom au territoire canadien qu'il traverse."],"src":"https://fr.vikidia.org/wiki/Yukon_(fleuve)","sw":"v","q":"Q104437","pays":["CA","US"],"c":["amerique-nord"]},"gambie":{"n":"Gambie","t":"fleuve","km":1130,"bassin":69931,"debit":2000,"src2":"Fouta-Djalon","emb":"océan Atlantique","bref":["Le fleuve Gambie est un cours d'eau d'Afrique de l'Ouest qui traverse la Guinée, le Sénégal puis la Gambie, pays qui s'étend sur ses deux rives."],"src":"https://fr.wikipedia.org/wiki/Gambie_(fleuve)","sw":"w","q":"Q160819","pays":["GM","GN","SN"],"c":["afrique"]},"gange":{"n":"Gange","t":"fleuve","km":2525,"bassin":1060000,"debit":12000,"src2":"glacier de Gangotri","emb":"golfe du Bengale","bref":["Le Gange est un fleuve indien qui naît dans l'Himalaya, coule dans le nord de la péninsule indienne et se jette dans le golfe du Bengale. Il mesure 2700 km de long. Son bassin hydrographique couvre environ un million de km2, (soit deux fois la superficie de la France et le tiers de la superficie de la république de l'Inde). Le Gange est le fleuve sacré de l'hindouisme. Le Gange est fortement pollué."],"src":"https://fr.vikidia.org/wiki/Gange","sw":"v","q":"Q5089","pays":["IN"],"c":["asie"]},"garonne":{"n":"Garonne","t":"rivière","km":647,"bassin":56000,"src2":"Pla de Beret","emb":"estuaire de la Gironde","bref":["La Garonne est un fleuve du nord de l'Espagne et du sud-ouest de la France. Elle parcourt 575 km ou 650 km, selon, qu'on inclut ou non, l'estuaire de la Gironde (75 km)."],"src":"https://fr.vikidia.org/wiki/Garonne","sw":"v","q":"Q5077","pays":["ES","FR"],"c":["europe"]},"godavari":{"n":"Godâvarî","t":"fleuve","km":1465,"bassin":313000,"debit":3061,"emb":"golfe du Bengale","bref":["Le Godavari (Godāvarī) est un fleuve important de l'Inde, long de 1 500 km qui prend sa source à Trimbak dans les Ghats occidentaux, près de Nasik, à près de 120 km au nord-est de Bombay dans l'État du Maharashtra, coule en direction du sud-est au travers du Dekkan, traverse le Telangana, et se jette dans le golfe du Bengale dans un delta commun avec la Krishnâ, en Andhra Pradesh."],"src":"https://fr.wikipedia.org/wiki/Godavari","sw":"w","q":"Q191314","pays":["IN"],"c":["asie"]},"guadalquivir":{"n":"Guadalquivir","t":"fleuve","km":657,"bassin":56978,"debit":164,"src2":"Sierra de Cazorla","emb":"golfe de Cadix","bref":["Le Guadalquivir est un grand fleuve du sud de l'Espagne. Son nom vient de l'arabe Wadi al-Kabir (واد الكبير), qui signifie « le grand fleuve ».","Il passe dans les villes de Cordoue et de Séville et se jette dans l'océan Atlantique à l'ouest du détroit de Gibraltar.","Il est navigable entre Séville et la mer. Du temps des Romains, des embarcations remontaient le fleuve jusqu'à Cordoue."],"src":"https://fr.vikidia.org/wiki/Guadalquivir","sw":"v","q":"Q14309","pays":["ES"],"c":["europe"]},"hudson":{"n":"Hudson","t":"fleuve","km":492,"bassin":34600,"debit":210,"emb":"Upper New York Bay","bref":["Le fleuve Hudson est un fleuve des États-Unis, dans l'est de l'État de New York. Il prend sa source dans les monts Adirondacks (lac Tears of the Cloudset se jette dans l'océan Atlantique à New York, dans la baie d'Upper New York après un trajet de 492 km.","L'estuaire de l'Hudson est un fait un fjord glaciaire créé entre 26 000 et 13 300 av. J-C au moment de la glaciation du Wisconsin. L'influence de la marée se ressent jusqu'à Troy très au nord. L'ancien lit de la rivière, aujourd'hui ennoyé est est très repérable sous l'océan Atlantique et s'étend jusqu'au bord du plateau continental.","L'Hudson est l'une des voies navigables les plus importantes de l'est des États-Unis, car c'est un axe de pénétration privilégié vers l'intérieur de l'Amérique du Nord. Au nord d'Albany se trouve la jonction avec le réseau du New York State Barge Canal System, qui relie l'Hudson au lac Champlain, aux Grands Lacs et au Saint-Laurent."],"src":"https://fr.vikidia.org/wiki/Hudson_(fleuve)","sw":"v","q":"Q3140","pays":["US"],"c":["amerique-nord"]},"ichim":{"n":"Ichim","t":"rivière","km":2450,"bassin":177000,"debit":56,"src2":"Hautes terres kazakhes","emb":"Irtych","bref":["L’Ichim ou Essil (en russe : Ишим, en kazakh : Есіл) est une rivière du Kazakhstan et de Russie et un affluent par la rive gauche de l’Irtych. Long de 2 450 km, il coule au Kazakhstan et dans le Sud de la Sibérie occidentale, en Russie."],"src":"https://fr.wikipedia.org/wiki/Ichim_(rivi%C3%A8re)","sw":"w","q":"Q191524","pays":["KZ","RU"],"c":["asie","europe"]},"ienissei":{"n":"Ienisseï","t":"fleuve","km":3487,"bassin":2580000,"debit":19800,"src2":"Touva","emb":"mer de Kara","bref":["L'Ienisseï est un fleuve russe situé en Sibérie centrale. Orienté sud-nord et suivant à peu près le méridien 90° Est, il sépare la Sibérie occidentale de la Sibérie orientale. Il finit par un delta en mer de Kara (golfe de l'Ienisseï). Il marque aussi selon la direction ouest-est la fin des régions peuplées et industrialisées. Au delà du fleuve commencent aussi les régions aux températures hivernales les plus sévères du pays."],"src":"https://fr.vikidia.org/wiki/Ienisse%C3%AF","sw":"v","q":"Q78707","pays":["RU"],"c":["asie","europe"]},"indus":{"n":"Indus","t":"fleuve","km":3180,"bassin":1165000,"debit":6600,"src2":"Sengge Zangbo","emb":"mer d'Arabie","bref":["23° 59′ 11″ N 67° 26′ 12″ E / 23.9863, 67.4368","L'Indus (connu dans l'Antiquité sous le nom de Sindh) est un fleuve de Chine, d'Inde et du Pakistan. Il a une longueur de 3 180 km. Le bassin de l'Indus a une superficie de 1 165 000 kilomètres carrés dont 453 000 kilomètres carrés se trouvent dans les contreforts de l'Himalaya, du Karakoram et de l'Hindou Kouch, le reste occupant les plaines semi-arides du Pakistan.","Mesuré à Sukkur, son débit moyen annuel est de 4 072 mètres cubes par seconde mais il est irrégulier sur l'année. Le débit moyen passe en effet de 906 mètres cubes par seconde en février à 13 300 mètres cubes par seconde en juillet."],"src":"https://fr.vikidia.org/wiki/Indus","sw":"v","q":"Q7348","pays":["PK","CN","IN"],"c":["asie"]},"inn":{"n":"Inn","t":"rivière","km":517,"bassin":25700,"debit":740,"src2":"lac de Lunghin","emb":"Danube","bref":["L'Inn (en romanche : En) est une rivière de l'Europe centrale, longue de 517 kilomètres. Elle prend sa source en Haute-Engadine, dans les Alpes suisses et continue son parcours en Suisse, en Autriche et ensuite en Allemagne. Elle termine son cours à Passau pour se jeter dans le Danube. Deux tiers de son cours passent à l'intérieur des Alpes.","En ce qui concerne le débit, le module de l'Inn à l'embouchure (740 m3/s) est supérieur à celui du Danube (690 m3/s) ; cela s'explique par les périodes de crues consécutives à des fortes précipitations et à la fonte des neiges dans les Alpes."],"src":"https://fr.wikipedia.org/wiki/Inn_(rivi%C3%A8re)","sw":"w","q":"Q14369","pays":["CH","AT","DE"],"c":["europe"]},"irrawaddy":{"n":"Irrawaddy","t":"fleuve","km":2170,"bassin":411000,"debit":13000,"src2":"Gyita Qu","emb":"mer d'Andaman","bref":["L'Irrawaddy ou Ayeyarwady est un fleuve d'Asie du Sud-Est d'environ 2 170 km de longueur. C'est le principal cours d'eau de la Birmanie. Sa large vallée centrale constitue la Birmanie « historique », d'abord habitée par les Pyus, puis par les Birmans. C'est aussi l'axe de communication le plus important du pays.","Autres transcriptions courantes : Ayeyarwaddy, Irraouadi ou Irraouaddi."],"src":"https://fr.wikipedia.org/wiki/Irrawaddy","sw":"w","q":"Q26076","pays":["MM"],"c":["asie"]},"irtych":{"n":"Irtych","t":"rivière","km":4248,"bassin":1643000,"debit":3000,"src2":"Altaï de Mongolie","emb":"Ob","bref":["L'Irtych est une rivière de Russie, affluent de l'Ob et située en Sibérie occidentale. Le nom signifie « rivière blanche ». Elle a son origine dans l'Altaï mongol, à 2 930 mètres d'altitude, dans la préfecture de l'Altaï (région autonome ouïgoure du Xinjiang, en Chine), presque sur la frontière mongole. Lorsque la rivière termine son cours au confluent de l'Ob, elle a parcouru 4 248 kilomètres après avoir traversé une partie de la Chine, le Kazakhstan oriental et la Russie."],"src":"https://fr.vikidia.org/wiki/Irtych","sw":"v","q":"Q128102","pays":["CN","KZ","RU"],"c":["asie","europe"]},"jourdain":{"n":"Jourdain","t":"fleuve","km":252,"bassin":18000,"src2":"plateau du Golan","emb":"mer Morte","bref":["Le Jourdain (de l'hébreu נהר הירדן, Nehar haYarden, qui veut dire la Rivière de la Peine, du Jugement, mais aussi descendre) est un fleuve du Proche-Orient qui a donné son nom à la Jordanie et à la Cisjordanie.","Du mont Hermon à la mer Morte, le Jourdain s'écoule sur 360 km.","Sa vallée est la plus basse du monde, puisqu'il rejoint la mer Morte à l'altitude de 392 m sous le niveau des océans.","31° 45′ 41″ N 35° 33′ 30″ E / 31.7613, 35.5582"],"src":"https://fr.vikidia.org/wiki/Jourdain","sw":"v","q":"Q40059","pays":["LB","PS","JO","SY","IL"],"c":["asie"]},"kama":{"n":"Kama","t":"rivière","km":1805,"bassin":507000,"debit":4100,"emb":"Volga","bref":["La Kama est une rivière de Russie européenne, affluent gauche de la Volga."],"src":"https://fr.wikipedia.org/wiki/Kama_(rivi%C3%A8re)","sw":"w","q":"Q79082","pays":["RU"],"c":["asie","europe"]},"katingan-river":{"n":"Katingan River","t":"fleuve","km":650,"emb":"mer de Java","q":"Q24878211","pays":["ID"],"c":["asie"]},"kolyma":{"n":"Kolyma","t":"fleuve","km":2129,"bassin":643000,"debit":3800,"emb":"mer de Sibérie orientale","bref":["La Kolyma (en russe : Колыма, en iakoute : Халыма, Khalyma) est un fleuve long de 2 129 km situé à l'extrémité nord-orientale de la Sibérie, en Russie."],"src":"https://fr.wikipedia.org/wiki/Kolyma_(fleuve)","sw":"w","q":"Q78879","pays":["RU"],"c":["asie","europe"]},"koura":{"n":"Koura","t":"fleuve","km":1360,"bassin":188000,"debit":443,"src2":"haut plateau arménien","emb":"mer Caspienne","bref":["La Koura (მტკვარი, Mt'k'vari, en géorgien, Kür en azéri, Kura ou Kuruçay en turc et Mtcouar en français au XIXe siècle) est un fleuve de Transcaucasie, qui s'écoule d'ouest en est entre le Caucase proprement dit et le petit Caucase. Elle était appelée Cyrus dans l'Antiquité. Le nom géorgien original de la Koura est Mtkvari, littéralement La Lente. La Koura est le plus grand fleuve de Transcaucasie."],"src":"https://fr.wikipedia.org/wiki/Koura_(fleuve)","sw":"w","q":"Q156557","pays":["TR","GE","AZ"],"c":["asie","europe"]},"krishna":{"n":"Krishnâ","t":"fleuve","km":1400,"bassin":258948,"debit":1641,"src2":"Mahabaleshwar","emb":"golfe du Bengale","bref":["La Krishna ou Kistna (Krishnā) est l'un des plus longs fleuves de l'Inde avec un cours d'environ 1 290 kilomètres. Prenant sa source dans les Ghats occidentaux, il coule en Inde du Sud dans le Karnataka et se jette dans le golfe du Bengale à Hamsaladeevi (en), dans l'Andhra Pradesh. Son vaste delta a créé une sorte de péninsule qui est traditionnellement considérée comme la limite septentrionale de la Côte de Coromandel."],"src":"https://fr.wikipedia.org/wiki/Krishna_(fleuve)","sw":"w","q":"Q193499","pays":["IN"],"c":["asie"]},"kumai-river":{"n":"Kumai River","t":"fleuve","km":175,"emb":"mer de Java","q":"Q24881791","pays":["ID"],"c":["asie"]},"lena":{"n":"Léna","t":"fleuve","km":4294,"bassin":2490000,"debit":16350,"src2":"Monts Baïkal","emb":"mer des Laptev","bref":["La Léna (en russe : Лeна) est un fleuve de Russie, situé en majorité dans l'Extrême-Orient russe. Il prend naissance dans la région du lac Baïkal (53° 57′ 07″ N 108° 05′ 27″ E / 53.952069, 108.090833) et, après un cours d'environ 4 000 km de long, d'orientation sud-nord, il se jette par un delta dans la mer des Laptev. Par la superficie de son bassin versant, il est le troisième fleuve de Russie (et le septième dans le monde). Par son débit moyen, il est le deuxième en Russie et le douzième dans le monde."],"src":"https://fr.vikidia.org/wiki/L%C3%A9na","sw":"v","q":"Q46841","pays":["RU"],"c":["asie","europe"]},"limpopo":{"n":"Limpopo","t":"fleuve","km":1750,"bassin":440000,"debit":170,"emb":"océan Indien","bref":["Le fleuve Limpopo (/lɪmˈpoʊpoʊ/) prend sa source en Afrique du Sud et coule généralement vers l'est à travers le Mozambique jusqu'à l'océan Indien. Le terme Limpopo est dérivé de Rivombo (Livombo/Lebombo), un groupe de colons Tsonga dirigé par Hosi Rivombo qui se sont installés dans les environs montagneux et ont donné à la région le nom de leur chef. La rivière est appelée Vhembe par les communautés locales Venda de la région où ce nom a maintenant été adopté par le gouvernement sud-africain comme municipalité de district dans le nord, un nom qui a également été suggéré en 2002 comme titre possible. pour la province mais est voté contre."],"src":"https://fr.wikipedia.org/wiki/Limpopo_(fleuve)","sw":"w","q":"Q173017","pays":["BW","MZ","ZA","ZW"],"c":["afrique"]},"loire":{"n":"Loire","t":"fleuve","km":1006,"bassin":117356,"debit":835,"src2":"Saint-Martial","emb":"golfe de Gascogne","bref":["La Loire est, avec une longueur de 1 006 kilomètres, le plus long fleuve s’écoulant entièrement en France. Elle prend sa source sur le versant sud du mont Gerbier-de-Jonc au sud-est du Massif central dans le département de l’Ardèche, et se jette dans l’océan Atlantique par un estuaire situé en Loire-Atlantique, dans la région des Pays de la Loire. Son cours est orienté d’abord du sud vers le nord jusqu’aux environs de Briare dans le Loiret, puis vers l’ouest.","La Loire torrentueuse et encaissée coule d’abord vers le nord ; à partir de Vorey (Haute-Loire) elle tend vers le nord-est, puis à nouveau le nord à partir du lac-barrage de Grangent. Elle prend globalement la direction du nord - nord-ouest à partir de Feurs (Loire), puis franchement celle du nord-ouest à partir de Digoin (Saône-et-Loire). Entre Châteauneuf (Loiret) et Orléans, les mariniers disaient qu’elle ruisselait déjà vers le soleil couchant, les contraignant à être contre le vent dominant."],"src":"https://fr.wikipedia.org/wiki/Loire","sw":"w","q":"Q1469","pays":["FR"],"c":["europe"]},"main":{"n":"Main","t":"rivière","km":524,"bassin":27292,"debit":195,"src2":"Haute-Franconie","emb":"Rhin","bref":["Le Main est une rivière allemande, affluent du Rhin. Sa longueur est de 524 km.","Il arrose les Länder de Bavière, Hesse et Bade-Wurtemberg.","Le Main est issu de la réunion de deux petites rivières : le Main rouge (71 km) et le Main blanc (45 km).","Dans sa partie centrale, il forme de grands méandres.","Il arrose les villes de Bayreuth (Main rouge), Bamberg, Wurtzbourg, Aschaffenbourg et Francfort-sur-le-Main, où son débit atteint 190 m3/s.","Le Main se jette dans le Rhin à Mayence."],"src":"https://fr.vikidia.org/wiki/Main_(rivi%C3%A8re)","sw":"v","q":"Q1670","pays":["DE"],"c":["europe"]},"martapura-river":{"n":"Martapura River","t":"rivière","km":25,"emb":"Barito","q":"Q6774211","pays":["ID"],"c":["asie"]},"mekong":{"n":"Mékong","t":"fleuve","km":4350,"bassin":810000,"debit":15000,"src2":"plateau tibétain","emb":"mer de Chine méridionale","bref":["Le Mékong est un fleuve d'Asie du Sud-Est d'une longueur de 4 500 km environ. Il est le quatrième fleuve d'Asie et le dixième au monde.","Le nom du fleuve est à l'origine Mae Nam Khong, donné par l'ethnie Taï qui est répartie dans tout le bassin ; mais un raccourci s'est vite effectué et les gens de ce peuple disent aujourd'hui Mae Khong, ce qui signifie « Mère de tous les fleuves » ou « Fleuve Kong ». Ce nom fut adopté par les Chinois, qui modifièrent un peu la prononciation, donnant Méigōng Hé (湄公河) ; le nom est redondant, signifiant « Fleuve Fleuve Kong ». Cette redondance existe dans presque toutes les langues aujourd'hui.","En arrivant au Vietnam, le Mékong prend le nom de Cuu Long qui signifie « neuf dragons », en référence aux neuf branches qui se jettent en mer de Chine méridionale."],"src":"https://fr.vikidia.org/wiki/M%C3%A9kong","sw":"v","q":"Q41179","pays":["CN","MM","TH","LA","KH","VN"],"c":["asie"]},"meuse":{"n":"Meuse","t":"fleuve","km":950,"bassin":36000,"debit":230,"src2":"Le Châtelet-sur-Meuse","emb":"mer du Nord","bref":["La Meuse est un fleuve européen de 950 km de long, qui traverse la France, la Belgique et les Pays-Bas et se jette dans la mer du Nord."],"src":"https://fr.vikidia.org/wiki/Meuse_(fleuve)","sw":"v","q":"Q41986","pays":["FR","BE"],"c":["europe"]},"mississippi":{"n":"Mississippi","t":"fleuve","km":3766,"bassin":2981000,"debit":12743,"src2":"lac Itasca","emb":"golfe du Mexique","bref":["Le Mississippi est un fleuve des États-Unis d'une longueur de 3 781 km. Si l'on combine le principal affluent, le Missouri (3 942 kilomètre), avec la partie avale du Mississipi (depuis Saint-Louis jusqu'au golfe du Mexique), la longueur obtenue est de 5 970 km, ce qui en fait l'un des plus grands fleuves du monde."],"src":"https://fr.vikidia.org/wiki/Mississippi_(fleuve)","sw":"v","q":"Q1497","pays":["US"],"c":["amerique-nord"]},"moselle":{"n":"Moselle","t":"rivière","km":544,"bassin":28286,"debit":315,"src2":"source de la Moselle","emb":"Rhin","bref":["La Moselle (en allemand: Mosel) est une rivière qui prend sa source en France, à Bussang, dans le massif des Vosges, borde ensuite une partie du Luxembourg et rejoint le Rhin à Coblence, en Allemagne.","Sa longueur totale est de 560 km : 314 km en France, 39 km faisant frontière entre le Luxembourg et l'Allemagne, et 208 exclusivement en Allemagne.","Autrefois, la Moselle se jetait dans la Meuse à hauteur de Pagny-sur-Meuse, en France. Cela explique son nom latin de Mosella, petite Meuse. La « capture » de la Moselle a eu lieu au début de l'ère quaternaire. À hauteur de Toul, la Moselle a été détournée de son cours par un affluent de la Meurthe : depuis lors, elle rejoint le Rhin. Son parcours tortueux est souvent connu sous le nom de boucles de la Moselle. Les pentes de rives allemandes sont plantées de vignes qui produisent un vin blanc très réputé (vin de Moselle)."],"src":"https://fr.vikidia.org/wiki/Moselle_(rivi%C3%A8re)","sw":"v","q":"Q1667","pays":["FR","DE","LU"],"c":["europe"]},"moskova":{"n":"Moskova","t":"rivière","km":473,"bassin":17600,"debit":109,"emb":"Oka","bref":["La Moskova (autrefois orthographiée Moskva en français, en russe : Москва, Moskvá ou Москва-река, Moskvá-reká, « Moskova-rivière », pour distinguer la rivière de la ville) est une rivière de Russie et un affluent de l'Oka, donc un sous-affluent du fleuve Volga.","Moskva, Moskova et Moscou sont trois transcriptions d'un même mot russe : Москва (Moskva). Le nom de la ville de Moscou est emprunté à celui de la rivière.","La bataille de la Moskova, que les Russes appellent « bataille de Borodino » (près de Mojaïsk), fait référence à la rivière qui coule non loin du champ de bataille."],"src":"https://fr.wikipedia.org/wiki/Moskova","sw":"w","q":"Q175117","pays":["RU"],"c":["asie","europe"]},"murray":{"n":"Murray","t":"fleuve","km":2508,"bassin":1061469,"debit":767,"src2":"Alpes australiennes","emb":"océan Indien","bref":["Le Murray est le plus long fleuve d'Australie. Son nom commémore un secrétaire d'État à la Guerre et aux Colonies, sir George Murray, de nationalité britannique (1772-1846). Il traverse trois États australiens : la Nouvelle-Galles du Sud, l'État de Victoria et l'Australie-Méridionale. Bien que l'étendue du bassin Darling-Murray s'élève à 1 061 469 kilomètres carrés, le débit annuel du fleuve reste faible et ne dépasse pas 748 mètres cubes/seconde par an."],"src":"https://fr.vikidia.org/wiki/Murray_(fleuve)","sw":"v","q":"Q183078","pays":["AU"],"c":["oceanie"]},"neckar":{"n":"Neckar","t":"rivière","km":362,"bassin":14000,"debit":140,"src2":"Neckarquelle","emb":"Rhin","bref":["Le Neckar est une rivière allemande, affluent de la rive droite du Rhin. Sa longueur est de 367 km.","Le Neckar prend sa source à Schwenningen, sur les coteaux de la Forêt-Noire, à 706 m d'altitude.","Il s'écoule d'abord vers le nord, traverse les villes de Tübingen, Stuttgart et Heilbronn.","Ensuite, il tourne vers l’ouest et traverse Heidelberg, où son débit moyen est de 130 m3/s.","Enfin, il se jette dans le Rhin à Mannheim, à 95 m d'altitude.","Le Neckar a été rendu navigable par une série de 27 écluses."],"src":"https://fr.vikidia.org/wiki/Neckar","sw":"v","q":"Q1673","pays":["DE"],"c":["europe"]},"neva":{"n":"Neva","t":"fleuve","km":74,"bassin":281000,"debit":2500,"src2":"lac Ladoga","emb":"baie de la Neva","bref":["La Néva est un fleuve de Russie, long seulement de 74 km, entre le lac Ladoga et la mer Baltique (golfe de Finlande).","La Néva est l'émissaire du lac Ladoga, mais elle reçoit aussi des affluents sur ses deux rives.","Elle termine son cours en traversant la ville de Saint-Pétersbourg en un delta actuellement occupé par les 42 îles qui forment la ville.","L'hiver, les eaux de la Néva sont gelées. La largeur moyenne du fleuve est de 500 mètres."],"src":"https://fr.vikidia.org/wiki/N%C3%A9va","sw":"v","q":"Q645","pays":["RU"],"c":["asie","europe"]},"niemen":{"n":"Niémen","t":"fleuve","km":937,"bassin":98200,"debit":678,"emb":"mer Baltique","bref":["Le Niémen est un fleuve d'Europe orientale, né en Biélorussie, traversant la Lituanie puis formant la frontière nord de l'oblast de Kaliningrad, l'exclave occidentale de la Russie, pour se jeter dans la lagune de Courlande sur le flanc oriental de la mer Baltique."],"src":"https://fr.wikipedia.org/wiki/Ni%C3%A9men","sw":"w","q":"Q5622","pays":["BY","LT","RU"],"c":["europe","asie"]},"niger":{"n":"Niger","t":"fleuve","km":4180,"bassin":2117700,"debit":8630,"src2":"Fouta-Djalon","emb":"golfe de Guinée","bref":["Le Niger est un fleuve d'Afrique de l'Ouest. Avec ses 4 184 kilomètres, il est le plus long en Afrique de l'Ouest et le troisième en Afrique après le Nil et le Congo. Le débit moyen annuel du fleuve à Sokoto est de 6 000 mètres cubes/seconde. Il n'a pourtant pas reçu les eaux de la Kaduna, ni celles de la Bénoué."],"src":"https://fr.vikidia.org/wiki/Niger_(fleuve)","sw":"v","q":"Q3542","pays":["BJ","GN","ML","NE","NG"],"c":["afrique"]},"nil":{"n":"Nil","t":"fleuve","km":6650,"bassin":3400000,"debit":2830,"src2":"lac Victoria","emb":"mer Méditerranée","bref":["Le Nil est un fleuve d'Afrique. Avec un cours de plus de 6 700 km, il est avec le fleuve Amazone, le plus long fleuve du monde. Il est issu de la rencontre du Nil Blanc et du Nil Bleu. Le Nil Blanc (en arabe : النيل الأبيض, alniyl al'abyad) prend sa source au lac Victoria (Ouganda, Kenya, Tanzanie) ; le Nil Bleu (en arabe : النيل الأزرق, alniyl al'azraq) est issu du lac Tana (Éthiopie). Ses deux branches s'unissant à Khartoum, capitale du Soudan actuel, le Nil se jette dans la Méditerranée en formant un delta au nord de l'Égypte. En comptant ses deux branches, le Nil traverse le Rwanda, le Burundi, la Tanzanie, l'Ouganda, l'Éthiopie, le Soudan du Sud, le Soudan et l'Égypte. Il longe également le Kenya et la république démocratique du Congo (respectivement avec les lacs Victoria et Albert), et son bassin versant concerne aussi l'Érythrée grâce à son affluent du Tekezé."],"src":"https://fr.wikipedia.org/wiki/Nil","sw":"w","q":"Q3392","pays":["SD","EG","UG","SS","BI","RW","ET"],"c":["afrique"]},"nil-blanc":{"n":"Nil Blanc","t":"rivière","km":2620,"bassin":1059000,"debit":878,"src2":"lac Victoria","emb":"Nil","bref":["Le Nil Blanc (en arabe : النيل الأبيض an-nīl al-'abyaḍ « le Nil blanc », ou البحرالأبيض al-baḥr al-'abyaḍ « la Mer blanche ») est un embranchement du Nil."],"src":"https://fr.wikipedia.org/wiki/Nil_Blanc","sw":"w","q":"Q4814791","pays":["RW","CD","SD","SS","TZ","UG"],"c":["afrique"]},"nil-bleu":{"n":"Nil Bleu","t":"rivière","km":1783,"bassin":325000,"debit":1525,"src2":"lac Tana","emb":"Nil","bref":["Le Nil Bleu ou Bahr el-Azrak (en amharique : ጥቁር አባይ, t’ikʼuri ābayi ; en oromo : Mormor or Abbayaa, litt. « père des courants » ; en arabe : النيل الأزرق, an-Nīl al-ʾAzraqu) est un cours d'eau d'Afrique de l'Est qui prend naissance au lac Tana sur les hauts plateaux abyssins, puis qui forme le Nil lors de sa confluence avec le Nil Blanc à Khartoum, au Soudan."],"src":"https://fr.wikipedia.org/wiki/Nil_Bleu","sw":"w","q":"Q882739","pays":["ET","SD"],"c":["afrique"]},"ob":{"n":"Ob","t":"fleuve","km":3650,"bassin":2990000,"debit":12492,"src2":"Katoun","emb":"mer de Kara","bref":["L'Ob ou Obi est un fleuve de la partie asiatique de la Russie. Il mesure 3 650 kilomètres de long (soit environ 3,6 fois la Loire, le plus grand fleuve français). Son bassin versant, le plus vaste d'Asie et le sixième du monde, a une superficie de 2 975 000 km2 (soit 5,4 fois la superficie de la France) : avec son principal affluent, l'Irtych, il forme pour une grande part la plaine de Sibérie occidentale qui est très marécageuse (voir plus loin les raisons)."],"src":"https://fr.vikidia.org/wiki/Ob","sw":"v","q":"Q973","pays":["RU"],"c":["asie","europe"]},"oder":{"n":"Oder","t":"fleuve","km":854,"bassin":125000,"debit":480,"emb":"mer Baltique","bref":["L’Oder (Odra en polonais, tchèque et sorabe ; Oder en allemand, français et anglais ; Suevus en latin classique ; Oddera ou Odera en latin médiéval ; Viadrus en néolatin) est un fleuve d’Europe centrale d’une longueur totale de 854 km.","Depuis sa source, située en République tchèque, l’Oder descend dans le Sud-Ouest de la Pologne, puis il est rejoint par la rivière Neisse (en polonais : Nysa) et constitue alors l’actuelle frontière naturelle entre l’Allemagne et la Pologne, jusqu’à son embouchure sur la lagune de Szczecin, qui donne sur la mer Baltique. C’est le deuxième plus long fleuve polonais après la Vistule."],"src":"https://fr.wikipedia.org/wiki/Oder","sw":"w","q":"Q552","pays":["PL","CZ","DE"],"c":["europe"]},"oka":{"n":"Oka","t":"rivière","km":1500,"bassin":245000,"debit":1258,"emb":"Volga","bref":["La rivière Oka (en russe : Ока) est une rivière d'Europe orientale de 1 500 km de long, qui coule en Russie. C'est l'affluent le plus important de la rive droite du bassin de la Volga."],"src":"https://fr.wikipedia.org/wiki/Oka_(Volga)","sw":"w","q":"Q172089","pays":["RU"],"c":["asie","europe"]},"okavango":{"n":"Okavango","t":"rivière","km":1600,"bassin":800000,"debit":500,"src2":"Plateau de Bié","emb":"delta de l'Okavango","bref":["L'Okavango, qui peut aussi s'écrire Okawango, Cubango ou Kubango, est un fleuve endoréique d'Afrique. Mesurant entre 1 600 et 1 800 km de long, depuis sa source jusqu'à son delta, c'est un des plus longs fleuves d'Afrique. Il prend sa source en Angola et après avoir traversé le Namibie pénètre au Botswana pour ne plus en sortir.","Son trait le plus exceptionnel est en effet d'être un des très rares fleuves de cette importance à ne rejoindre ni un grand lac, ni la mer ou l'océan : l'Okavango coule vers l'intérieur des terres, jusqu'à former un gigantesque delta, le delta de l'Okavango, dans le désert du Kalahari. Le delta est tellement grand, que l'évaporation suffit à faire disparaître l'eau amenée par le fleuve qui, ainsi, ne rejoint jamais la mer. Ce phénomène rare est appelé l'endoréisme."],"src":"https://fr.vikidia.org/wiki/Okavango","sw":"v","q":"Q188773","pays":["AO","BW","NA"],"c":["afrique"]},"oleniok":{"n":"Oleniok","t":"fleuve","km":2270,"bassin":219000,"debit":1210,"src2":"plateau de Sibérie centrale","emb":"golfe de l'Oleniok","bref":["L'Oleniok (ou Oléniok ; en russe : Оленёк, en iakoute : Өлөөн) est un fleuve long de 2 292 km situé dans le nord-est de la Sibérie en Russie asiatique. Il coule sur le territoire du kraï de Krasnoïarsk et de la République de Sakha (Yakoutie)."],"src":"https://fr.wikipedia.org/wiki/Oleniok","sw":"w","q":"Q26799","pays":["RU"],"c":["asie","europe"]},"orange":{"n":"Orange","t":"fleuve","km":2200,"bassin":973000,"debit":800,"src2":"Drakensberg","emb":"océan Atlantique","bref":["L'Orange, long de 2 160 kilomètres, est le plus long fleuve d'Afrique du Sud."],"src":"https://fr.wikipedia.org/wiki/Orange_(fleuve)","sw":"w","q":"Q181475","pays":["LS","NA","ZA"],"c":["afrique"]},"orenoque":{"n":"Orénoque","t":"fleuve","km":2140,"bassin":989000,"debit":30000,"emb":"océan Atlantique","bref":["L'Orénoque (en espagnol : río Orinoco) est un fleuve de Colombie et du Venezuela, en Amérique du Sud. Sa longueur est de 2 140 km. Il n'est traversé que par deux ponts.","Il prend sa source sur le plateau des Guyanes et se jette dans l'océan Atlantique par un vaste delta. Il arrose les deux villes vénézuéliennes de Ciudad Bolívar et Ciudad Guayana.","L'Orénoque a un débit de 36 000 m3 par seconde, ce qui en fait pour ce critère le 3e fleuve au monde, après l'Amazone (205 000 m3/s) et le Congo (42 000 m3/s).","Source : cette page a été partiellement adaptée de la page Orénoque de Wikipédia.","2° 19′ N 63° 22′ W / 2.31, -63.36"],"src":"https://fr.vikidia.org/wiki/Or%C3%A9noque","sw":"v","q":"Q131792","pays":["VE","CO"],"c":["amerique-sud"]},"oubangui":{"n":"Oubangui","t":"rivière","km":1060,"bassin":772800,"debit":5936,"src2":"Mbomou","emb":"Congo","bref":["L'Oubangui (aussi écrit Ubangi) est une rivière d'Afrique, et un affluent majeur du fleuve Congo en Afrique centrale. Elle s'écoule vers l'ouest, formant la frontière entre la République centrafricaine et la république démocratique du Congo."],"src":"https://fr.wikipedia.org/wiki/Oubangui","sw":"w","q":"Q171649","pays":["CF","CG","CD"],"c":["afrique"]},"oural":{"n":"Oural","t":"fleuve","km":2428,"bassin":231000,"debit":400,"src2":"Oural","emb":"mer Caspienne","bref":["L'Oural (en russe : Урал, en kazakh : Жайық), appelé Iaïk avant 1775, est un fleuve situé aux confins de l'Est de l'Europe. Il parcourt la Russie et le Kazakhstan. Il prend sa source dans la chaîne de montagnes de l'Oural en Russie, traverse l'Ouest du Kazakhstan avant de se jeter dans la mer Caspienne. Il réalise 2 428 kilomètres² sur toute sa longueur, et est l'un des fleuves russes les plus connus.","Son tracé constitue la limite entre le territoire kazakh situé en Asie et le continent européen."],"src":"https://fr.vikidia.org/wiki/Oural_(fleuve)","sw":"v","q":"Q80240","pays":["KZ","RU"],"c":["asie","europe"]},"paraguay":{"n":"Paraguay","t":"rivière","km":2621,"bassin":1135624,"debit":4696,"src2":"Chapada dos Parecis","emb":"Paraná","bref":["Le río Paraguay (en portugais Rio Paraguai) est un important cours d'eau d'Amérique du Sud, constituant le principal affluent du rio Paraná et coulant du nord au sud sur le territoire de quatre pays, le Brésil, la Bolivie, le Paraguay, et l'Argentine. Il est avec le Paraná la principale voie fluviale de la république du Paraguay et la seconde la plus longue du continent américain après l'Amazone. C'est une importante voie de transport maritime et un couloir commercial qui assure un lien fondamental entre l'océan Atlantique et les nations sans littoral que sont le Paraguay et la Bolivie. Son bassin a une superficie de 1 095 000 km2, soit deux fois celle de la France métropolitaine."],"src":"https://fr.wikipedia.org/wiki/R%C3%ADo_Paraguay","sw":"w","q":"Q179396","pays":["BR","PY","AR","BO"],"c":["amerique-sud"]},"parana":{"n":"Paraná","t":"rivière","km":4880,"bassin":2582672,"debit":16000,"src2":"rio Grande","emb":"río de la Plata","bref":["Le rio Paraná est un fleuve d'Amérique du Sud qui a son origine au Brésil dans la serra da Mantiqueira pour terminer son cours dans le rio de la Plata, un espace maritime bordier de l'océan Atlantique. Par définition, le fleuve naît du confluent du rio Paranaiba et du rio Grande. Mais la mesure d'un fleuve doit se faire depuis son origine réelle jusqu'à la mer. Aussi, en considérant la source la plus lointaine, faut-il compter le parcours du rio Grande, la plus longue branche. Nous obtenons alors un cours d'eau de 4 099 kilomètres de long."],"src":"https://fr.vikidia.org/wiki/Rio_Paran%C3%A1","sw":"v","q":"Q127892","pays":["AR","BR","PY"],"c":["amerique-sud"]},"petchora":{"n":"Petchora","t":"fleuve","km":1809,"bassin":322000,"debit":4100,"src2":"Oural","emb":"mer de Petchora","bref":["La Petchora (en russe : Печора, en komi : Печӧра) est un fleuve de Russie. Il traverse la république russe des Komis et le district autonome de Nénétsie. Son cours est long de 1 809 km. Le débit inter annuel ou module de la Petchora est de 4 515 m3/s et le classe à la troisième place des fleuves d'Europe derrière la Volga (8 087 m3/s) et le Danube (6 488 m3/s) et devant le Rhin (2 278 m3/s)."],"src":"https://fr.wikipedia.org/wiki/Petchora_(fleuve)","sw":"w","q":"Q8168","pays":["RU"],"c":["asie","europe"]},"po":{"n":"Pô","t":"fleuve","km":652,"bassin":74000,"debit":1460,"src2":"Pian del Re","emb":"mer Adriatique","bref":["Le Pô est un fleuve qui coule en Italie. Il est long de 652 km, prend sa source dans le massif des Alpes au pied du Monte Viso et traverse le nord de l'Italie d'ouest en est. Il se jette dans la mer Adriatique. Son embouchure est un immense delta.","Le Pô transporte beaucoup de débris, qui en raison de la faible pente, se déposent au fond du lit. Il faut contenir le fleuve par des digues et souvent le fleuve coule plus haut que la plaine, qu'il menace d'inondation en période de crue.","Le Pô traverse les villes de Turin, Crémone, Plaisance et Ferrare.","La plaine du Pô est la région la plus riche et la plus productive de l'Italie. En Italie, un mouvement séparatiste demande une autonomie du Nord de l'Italie par rapport au Sud."],"src":"https://fr.vikidia.org/wiki/P%C3%B4","sw":"v","q":"Q643","pays":["IT"],"c":["europe"]},"potomac":{"n":"Potomac","t":"fleuve","km":665,"bassin":38100,"debit":306,"src2":"North Branch Potomac River","emb":"baie de Chesapeake","bref":["Le Potomac est un fleuve de l'Est des États-Unis, qui se jette dans la baie de Chesapeake dans l'océan Atlantique."],"src":"https://fr.wikipedia.org/wiki/Potomac","sw":"w","q":"Q179444","pays":["US"],"c":["amerique-nord"]},"rhin":{"n":"Rhin","t":"fleuve","km":1233,"bassin":185000,"debit":2200,"src2":"lac de Toma","emb":"mer du Nord","bref":["Le Rhin est un fleuve international long de 1 320 kilomètres. Il prend sa source dans les Alpes suisses. Il longe ensuite : l'Autriche, le Liechtenstein qu'il sépare de la Suisse. Ensuite, il sépare l'Allemagne de la Suisse, puis de la France. Il traverse l'Ouest de l'Allemagne et les Pays-Bas. Il se jette dans la mer du Nord dans un delta commun avec la Meuse.","Deux départements français portent son nom : le Haut-Rhin et le Bas-Rhin."],"src":"https://fr.vikidia.org/wiki/Rhin","sw":"v","q":"Q584","pays":["CH","AT","LI","DE","FR"],"c":["europe"]},"rhone":{"n":"Rhône","t":"fleuve","km":812,"bassin":98000,"debit":1780,"src2":"glacier du Rhône","emb":"mer Méditerranée","bref":["Le Rhône est un fleuve d'Europe, long de 812 kilomètres (un tiers en Suisse et deux tiers en France).","Il prend sa source dans le glacier du Rhône, en Suisse, à une altitude de 2 209 m, à l'extrémité orientale du Valais, dans le massif des Alpes uranaises. Il parcourt 290 km en Suisse, se jetant dans le Léman pour en sortir à Genève. Il entre ensuite en France, où il parcourt 522 km, selon l'Encyclopédie Larousse, ou 545 km, selon le SANDRE, prenant son virage vers le sud à Lyon. Il termine son cours dans le delta de Camargue pour se jeter dans la mer Méditerranée. Port-Saint-Louis-du-Rhône est la dernière ville traversée par le Rhône.","De tous les fleuves s'écoulant en Méditerranée, le débit du Rhône est le deuxième plus important après celui du Nil, si l'on ne tient pas compte de la mer Noire, où se jettent en particulier le Danube et le Don. Finissant son cours dans une mer sans marée, le fleuve a formé un delta avec des bras qui se sont déplacés principalement d'ouest en est au cours de l'histoire. Désormais endigué, ce delta est figé, hormis lors de crues exceptionnelles comme en 1993, 1994 et 2003."],"src":"https://fr.wikipedia.org/wiki/Rh%C3%B4ne","sw":"w","q":"Q602","pays":["CH","FR"],"c":["europe"]},"rio-biobio":{"n":"río Biobío","t":"fleuve","km":380,"bassin":23920,"debit":899,"emb":"océan Pacifique","bref":["Le río Biobío (également orthographié Bío-Bío ou Bío Bío) est un fleuve qui traverse une partie de la zone sud du Chili. C'est l'un des principaux du pays, tant par ses caractéristiques de débit et de longueur, que par son importance historique et économique."],"src":"https://fr.wikipedia.org/wiki/Rio_Biob%C3%ADo","sw":"w","q":"Q93360","pays":["CL"],"c":["amerique-sud"]},"rio-caqueta":{"n":"río Caquetá","t":"rivière","km":2820,"bassin":282000,"debit":13915,"emb":"Amazone","bref":["Le río Caquetá (Colombie) ou rio Japurá (Brésil) est une rivière importante de l'Amazonie, de 2 420 km de longueur, et un affluent de l'Amazone qui porte à cet endroit le nom de rio Solimões. Il s'agit du 5e affluent du système amazonien par sa longueur et le 3e pour son débit (18 620 m3/s) d'autant plus remarquable que son bassin n'est pas très étendu. Au confluent, il augmente d'un quart le volume du fleuve. Il s'y déplace autant d'eau que dans le Mississippi (pour un bassin versant 12 fois moins vaste) parce qu'il draine la partie la plus arrosée du bassin amazonien."],"src":"https://fr.wikipedia.org/wiki/R%C3%ADo_Caquet%C3%A1","sw":"w","q":"Q171840","pays":["BR","CO"],"c":["amerique-sud"]},"rio-de-la-plata":{"n":"río de la Plata","t":"fleuve","km":290,"bassin":4144000,"debit":22000,"emb":"océan Atlantique","bref":["Le río de la Plata est une mer épicontinentale (ou un golfe) ou, selon d'autres géographes, un estuaire maritime constituant l'embouchure des fleuves Paraná et Uruguay et situé entre l'Argentine et l'Uruguay. Son nom signifie « rivière de l'argent ». Sa limite orientale correspond à une ligne joignant le cabo San Antonio, en Argentine à la punta del Este, en Uruguay."],"src":"https://fr.vikidia.org/wiki/R%C3%ADo_de_la_Plata","sw":"v","q":"Q35827","pays":["AR","UY"],"c":["amerique-sud"]},"rio-grande":{"n":"río Grande","t":"fleuve","km":3051,"bassin":471900,"debit":85,"emb":"golfe du Mexique","bref":["Le río Grande, nommé ainsi aux États-Unis, nommé río Bravo del Norte ou plus communément río Bravo au Mexique, est un fleuve long de 3 060 km qui prend sa source dans le Colorado et sert de frontière entre le Mexique et les États-Unis (ce qui fait de lui une limite naturelle) sur les 2 038 derniers kilomètres de son cours."],"src":"https://fr.wikipedia.org/wiki/R%C3%ADo_Grande_(fleuve)","sw":"w","q":"Q160636","pays":["US","MX"],"c":["amerique-nord"]},"rio-jurua":{"n":"rio Juruá","t":"rivière","km":3100,"bassin":224000,"debit":4765,"emb":"Amazone","bref":["Le rio Juruá est un des principaux affluents de l'Amazone. Il rejoint la longue section du fleuve qui porte le nom de rio Solimões ; il coule au Pérou et surtout au Brésil."],"src":"https://fr.wikipedia.org/wiki/Rio_Juru%C3%A1","sw":"w","q":"Q117526","pays":["BR","PE"],"c":["amerique-sud"]},"rio-madeira":{"n":"rio Madeira","t":"rivière","km":1450,"bassin":1420000,"debit":31200,"src2":"río Mamoré","emb":"Amazone","bref":["Le rio Madeira est un cours d'eau du Brésil et un des principaux affluents de l'Amazone. En considérant la source la plus lointaine, le rio Madeira coule d'abord en Bolivie mais sous d'autres noms. À son confluent avec l'Amazone, le système totalise 3 352 kilomètres. Son bassin versant à une superficie de 1 420 000 kilomètres carrés. Son débit moyen annuel est de 31 900 mètres cubes/seconde, ce qui le classe pour cette spécialité premier affluent du monde et quatrième cours d'eau sur Terre. Il roule plus d'eau que le Brahmapoutre !"],"src":"https://fr.vikidia.org/wiki/Rio_Madeira","sw":"v","q":"Q118251","pays":["BR","BO"],"c":["amerique-sud"]},"rio-magdalena":{"n":"río Magdalena","t":"fleuve","km":1528,"bassin":260000,"debit":7200,"src2":"Nœud d'Almaguer","emb":"mer des Caraïbes","bref":["Le Magdalena est le fleuve le plus important de Colombie. Il coule dans une large vallée entre les cordillères Centrale et Orientale des Andes colombiennes, en direction du nord à travers tout le pays."],"src":"https://fr.wikipedia.org/wiki/R%C3%ADo_Magdalena","sw":"w","q":"Q191829","pays":["CO"],"c":["amerique-sud"]},"rio-negro":{"n":"rio Negro","t":"rivière","km":2250,"bassin":720114,"debit":30000,"emb":"Amazone","bref":["Le rio Negro ou río Guainía est une rivière d'Amérique du Sud de 2 250 km et un affluent de l'Amazone en rive gauche (soit au nord de l'Amazone), qui irrigue notamment la ville de Manaus.","Le rio Negro a été inscrit en 2018 sur la liste des zones protégées par la convention de Ramsar.","Les Caboclos, descendants de colons portugais et d'Amérindiens, vivent sur les berges de quelques canaux latéraux du rio Negro."],"src":"https://fr.wikipedia.org/wiki/Rio_Negro_(Amazone)","sw":"w","q":"Q118771","pays":["BR","CO","VE"],"c":["amerique-sud"]},"rio-purus":{"n":"rio Purus","t":"rivière","km":2960,"bassin":365000,"debit":8,"emb":"rio Solimões","bref":["Le rio Purus est un cours d'eau du Pérou et du Brésil, affluent de l'Amazone et d'une longueur de 3 210 kilomètres. Il prend sa source au Pérou, à 530 mètres d'altitude, dans la région d'Ucayali. Son cours a une orientation générale vers le nord-est."],"src":"https://fr.vikidia.org/wiki/Rio_Purus","sw":"v","q":"Q26271","pays":["BR"],"c":["amerique-sud"]},"rio-sao-francisco":{"n":"rio São Francisco","t":"fleuve","km":2814,"bassin":641000,"debit":3,"src2":"Serra da Canastra National Park","emb":"océan Atlantique","bref":["Le rio São Francisco est un important fleuve d'Amérique du Sud. Son système-fluvial est le quatrième du sous-continent. Le cours d'eau se trouve entièrement au Brésil. Il porte le nom d'un chef jésuite du XVIe siècle, Sâo Francisco Borja. Il prend sa source dans la sierra da Canastra, dans l'État du Minas Gerais. Long de 2 914 kilomètres, il termine son cours dans l'océan Atlantique. La superficie de son bassin s'élève â 631 200 kilomètres carrés. Longtemps utilisé comme voie de communication entre le Sud et le Nord-Est du Brésil, il est aujourd'hui une source d'hydroélectricité et d'irrigation pour ces mêmes régions."],"src":"https://fr.vikidia.org/wiki/Rio_S%C3%A3o_Francisco","sw":"v","q":"Q142148","pays":["BR"],"c":["amerique-sud"]},"rio-tocantins":{"n":"rio Tocantins","t":"fleuve","km":2450,"bassin":770000,"debit":11364,"emb":"Marajó Bay","bref":["Le rio Tocantins est un important fleuve brésilien qui naît dans l'État de Goiás."],"src":"https://fr.wikipedia.org/wiki/Rio_Tocantins","sw":"w","q":"Q156054","pays":["BR"],"c":["amerique-sud"]},"rio-uruguay":{"n":"rio Uruguay","t":"rivière","km":1790,"bassin":365000,"debit":5,"src2":"rio Pelotas","emb":"río de la Plata","bref":["Le río Uruguay (ou rio Uruguai en portugais) est un fleuve d'Amérique du Sud."],"src":"https://fr.wikipedia.org/wiki/R%C3%ADo_Uruguay","sw":"w","q":"Q18278","pays":["UY","BR","AR"],"c":["amerique-sud"]},"riviere-arkansas":{"n":"rivière Arkansas","t":"rivière","km":2364,"bassin":505000,"debit":240,"src2":"rivière Arkansas fourche Est","emb":"Mississippi","bref":["L'Arkansas (Arkansas River en anglais) est un affluent du Mississippi dont le cours traverse les États du Colorado, du Kansas, de l'Oklahoma et de l'Arkansas. Long de 2 334 km, c'est le quatrième cours d'eau le plus long des États-Unis."],"src":"https://fr.wikipedia.org/wiki/Arkansas_(rivi%C3%A8re)","sw":"w","q":"Q8319","pays":["US"],"c":["amerique-nord"]},"riviere-des-perles":{"n":"rivière des Perles","t":"fleuve","km":2400,"bassin":437000,"debit":9500,"src2":"Nanpan","emb":"mer de Chine méridionale","bref":["La rivière des Perles (en chinois Zhū Jiang), dans le Sud-Est de la Chine, est issue de la réunion de deux cours d'eau : le Baini Jiang et le Liuxi Jiang. Ce toponyme s'étend parfois au fleuve voisin, le Xi Jiang, mais cet usage est abusif.","La rivière des Perles arrose principalement la ville de Canton (Guangzhou)."],"src":"https://fr.vikidia.org/wiki/Rivi%C3%A8re_des_Perles","sw":"v","q":"Q201463","pays":["CN"],"c":["asie"]},"riviere-kasai":{"n":"Rivière Kasaï","t":"rivière","km":2272,"bassin":880200,"debit":12000,"emb":"Congo","bref":["Le Kasayi ou Kasaï (en portugais Cassai) est une rivière d'Afrique centrale, affluent du Congo."],"src":"https://fr.wikipedia.org/wiki/Kasa%C3%AF_(rivi%C3%A8re)","sw":"w","q":"Q186541","pays":["AO","CD"],"c":["afrique"]},"riviere-missouri":{"n":"rivière Missouri","t":"rivière","km":3726,"bassin":1371010,"debit":2478,"emb":"Mississippi","bref":["Le Missouri est une importante rivière des États-Unis. Sa longueur est de 3 767 km.","C'est le principal affluent du fleuve Mississippi. Son débit est très variable selon la saison : d'un minimum de 120 mètres cubes par seconde il peut atteindre un maximum de 25 500 mètres cubes par seconde. Le débit moyen annuel s'élève à 2 300 mètres cubes par seconde. Son bassin versant couvre 1 376 180 kilomètres carrés, soit le quatrième d'Amérique du Nord."],"src":"https://fr.vikidia.org/wiki/Missouri_(rivi%C3%A8re)","sw":"v","q":"Q5419","pays":["US"],"c":["amerique-nord"]},"riviere-ohio":{"n":"rivière Ohio","t":"rivière","km":1579,"bassin":528100,"debit":7973,"src2":"Allegheny","emb":"Mississippi","bref":["L'Ohio est une rivière de l'est des États-Unis et un affluent de rive gauche du Mississippi. C'est le principal affluent de ce fleuve par son débit et le troisième par sa longueur. Il occupe la partie Nord-Est du bassin du Mississippi. Il a une importance capitale dans l'histoire des États-Unis, que ce soit pour les nations autochtones ou les colons européens. L'Ohio a constitué une voie de transport privilégiée lors de la Conquête de l'Ouest. En effet, elle traverse pas moins de six États, et son bassin hydrographique s'étend sur quatorze États, comprenant la plupart des États du sud-est du pays. Son affluent principal est le Tennessee. Au XVIIIe siècle, l'Ohio constituait la frontière méridionale des États du Nord, marquant de facto la limite entre les États pratiquant l'esclavage et ceux l'ayant aboli."],"src":"https://fr.wikipedia.org/wiki/Ohio_(rivi%C3%A8re)","sw":"w","q":"Q4915","pays":["US"],"c":["amerique-nord"]},"riviere-rouge":{"n":"rivière Rouge","t":"rivière","km":2189,"bassin":233000,"debit":1900,"src2":"fourche Prairie Dog Town de la rivière Red","emb":"rivière Atchafalaya","bref":["La rivière Rouge (en anglais : Red River), parfois appelée la rivière Rouge du Sud, est une rivière des États-Unis et un des principaux affluents du fleuve Mississippi. Son nom vient de la couleur rouge de ses eaux. Son débit moyen est de 1 585 m3/s."],"src":"https://fr.wikipedia.org/wiki/Rivi%C3%A8re_Rouge_(Mississippi)","sw":"w","q":"Q156032","pays":["US"],"c":["amerique-nord"]},"salouen":{"n":"Salouen","t":"fleuve","km":2815,"bassin":325000,"debit":4876,"src2":"Nagqu","emb":"mer d'Andaman","bref":["La Salouen (tibétain : རྒྱ་མོ་དངུལ་ཆུ་, Wylie : rGya mo dNGul chu ; chinois : 怒江 ; pinyin : nù jiāng, Birman : Thanlwin Myit, Thaï : สาละวิน (Saalawin), en français fleuve nu ou fleuve en colère) est un fleuve de Chine et de Birmanie, dont le bassin s'étend également sur la Thaïlande, le deuxième par sa longueur en Asie du Sud-Est après le Mékong, mais devant l'Irrawaddy. Son bassin, étroit et peu peuplé, est surtout caractérisé par une très riche biodiversité aujourd'hui menacée par les projets de construction de nombreux barrages hydroélectriques perturbant l'écosystème."],"src":"https://fr.wikipedia.org/wiki/Salouen","sw":"w","q":"Q26422","pays":["CN","TH","MM"],"c":["asie"]},"save":{"n":"Save","t":"rivière","km":945,"bassin":95719,"debit":1722,"emb":"Danube","bref":["La Save (en allemand : Save, en serbe, slovène, croate et bosnien : Sava, en hongrois : Száva) est une rivière qui coule dans certains États slaves : la Slovénie, la Croatie, la Bosnie-Herzégovine et la Serbie. C'est un affluent de rive droite du Danube. Il mesure 940 km de long, mais près de 1000 km en comptant la source de la Save, la Sava Dolinka."],"src":"https://fr.vikidia.org/wiki/Save_(Danube)","sw":"v","q":"Q14383","pays":["SI","HR","BA","RS"],"c":["europe"]},"seine":{"n":"Seine","t":"fleuve","km":777,"bassin":78650,"debit":500,"src2":"sources de la Seine","emb":"Manche","bref":["La Seine est un fleuve de la moitié nord de la France. Son bassin est surtout composé de plaines et de plateaux avec une majorité de terrains perméables. La pente est faible et le débit moyen. C'est un fleuve qui a été rendu navigable par des aménagements (barrages avec écluses). Il est relié par des canaux, aujourd'hui pour la plupart inadaptés aux bateaux modernes, aux fleuves du Nord et de Belgique, au Rhin et à la Loire."],"src":"https://fr.vikidia.org/wiki/Seine","sw":"v","q":"Q1471","pays":["FR"],"c":["europe"]},"senegal":{"n":"Sénégal","t":"fleuve","km":1050,"bassin":419575,"debit":640,"src2":"Bafing","emb":"océan Atlantique","bref":["Le Sénégal est un fleuve de l'Afrique occidentale. Il a 1790 km de longueur. Il se jette dans l'océan Atlantique en aval de la ville de Saint-Louis dans le nord du Sénégal. Son bassin versant est de 337 000 km2 (soit 60% de la superficie de la France métropolitaine) et s'étend sur la Guinée, le Mali, le Sénégal et la Mauritanie.","Le Sénégal nait en Guinée dans le massif du Fouta-Djalon. Deux rivières qui se rejoignent à Bafoulabé (Mali) forment le Sénégal : le Bafing (considéré comme la branche-mère) et le Bakhoy. Par une série de chutes d'eau il parvient à Kayes au Mali. Il traverse la région semi-désertique du Ferlo (Sénégal) et sa vallée se transforme souvent en marécages, ce qui forme une sorte de delta intérieur. Il sert ensuite de frontière entre le Sénégal et la Mauritanie."],"src":"https://fr.vikidia.org/wiki/S%C3%A9n%C3%A9gal_(fleuve)","sw":"v","q":"Q3569","pays":["MR","SN","ML"],"c":["afrique"]},"spree":{"n":"Spree","t":"rivière","km":382,"bassin":10100,"debit":36,"src2":"Ebersbach","emb":"Havel","bref":["La Sprée /spʁe/ ou la Spree (en allemand : Die Spree /ʃpʁeː/ ; en tchèque : Spréva) est une rivière allemande et tchèque, affluent de la Havel, donc sous-affluent de l'Elbe."],"src":"https://fr.wikipedia.org/wiki/Spr%C3%A9e","sw":"w","q":"Q1684","pays":["DE"],"c":["europe"]},"syr-daria":{"n":"Syr-Daria","t":"fleuve","km":2212,"bassin":219000,"debit":703,"emb":"Petite mer d'Aral","bref":["Le Syr-Daria est un fleuve d'Asie centrale qui traverse l'Ouzbekistan, le Tadjikistan et le Kazakhstan. Il fut connu dans l'Antiquité sous le nom de Iaxarte ou Jaxartes. Il est formé au confluent de deux cours d'eau, le Naryn et le Kara-Daryya (ou Qoradaryo) dans l'Est de la vallée de Ferghana (Ouzbekistan) et plus précisément dans la province de Namangan. Le Naryn, celui qui nous intéresse parce que le plus long, prend sa source (41° 44′ 53″ N 78° 13′ 53″ E / 41.748048, 78.231348) dans le Tian Shan (montagnes Célestes), au sud-est de l'Yssik Kül, au Kirghizistan."],"src":"https://fr.vikidia.org/wiki/Syr-Daria","sw":"v","q":"Q483159","pays":["KZ","UZ","TJ","KG"],"c":["asie","europe"]},"tage":{"n":"Tage","t":"fleuve","km":1007,"bassin":80602,"debit":500,"src2":"Fuente de García","emb":"océan Atlantique","bref":["Le Tage est un fleuve hispano-portugais qui prend sa source dans la sierra de Albarracin, traverse les terres espagnoles, passe à Tolède et à Talavera de la Reina, poursuit son cours au Portugal où il se jette non loin de Lisbonne, dans la mer de Paille, une baie de l'océan Atlantique parfois considérée à tort comme l'estuaire du Tage. Son principal affluent est le Zêzere, un cours d'eau portugais.","Avec un parcours de 1 007 km, c'est le plus long fleuve de la péninsule Ibérique.","L'embouchure du Tage est originale et même complexe. Elle se compose d'un delta, assez réduit pour un fleuve de cette dimension, suivi d'une baie intérieure assez vaste. Celle-ci ne communique avec l'océan Atlantique que par un étroit goulet. Sur les rives de cette baie, appelée mer de Paille se sont développées la ville de Lisbonne et son agglomération."],"src":"https://fr.vikidia.org/wiki/Tage","sw":"v","q":"Q14294","pays":["PT","ES"],"c":["europe"]},"tamise":{"n":"Tamise","t":"fleuve","km":334,"bassin":15300,"debit":66,"src2":"Kemble","emb":"mer du Nord","bref":["La Tamise (Thames en anglais) est le principal fleuve du Royaume-Uni. Sa longueur est de 346 kilomètres. Elle se jette dans la mer du Nord. Elle traverse l'Angleterre.","Elle prend sa source au bord des collines des Cotswolds, à Thames Head. Elle traverse alors Oxford, Wallingford, Reading, Sonning, Henley-on-Thames, Marlow, Maidenhead, Eton, Windsor, Hampton, Kingston, Richmond upon Thames avant d’entrer dans Londres. Elle coule sous beaucoup de ponts dans la capitale:"],"src":"https://fr.vikidia.org/wiki/Tamise","sw":"v","q":"Q19686","pays":["GB"],"c":["europe"]},"tarim":{"n":"Tarim","t":"rivière","km":2030,"bassin":557000,"debit":920,"emb":"bassin du Tarim","bref":["Le Tarim (ouïghour : تارىم دەرياسى ; Tarim deryasi ; chinois : 塔里木河 ; pinyin : Tǎlǐmù hé) est un fleuve sans embouchure traversant le désert du Taklamakan dans le sud du Xinjiang, une des cinq régions autonomes de République populaire de Chine. Il forme le bassin du Tarim."],"src":"https://fr.wikipedia.org/wiki/Tarim_(fleuve)","sw":"w","q":"Q237901","pays":["CN"],"c":["asie"]},"terek":{"n":"Terek","t":"fleuve","km":623,"bassin":43200,"debit":305,"src2":"mont Kazbek","emb":"mer Caspienne","bref":["Le Terek (en russe : Терек ; en géorgien : თერგი ; en avar : Терек) est l'un des principaux fleuves du Caucase, d'une longueur de 623 kilomètres. Il coule sur les territoires de la Géorgie et de la Russie."],"src":"https://fr.wikipedia.org/wiki/Terek_(fleuve)","sw":"w","q":"Q82776","pays":["GE","RU"],"c":["europe","asie"]},"tibre":{"n":"Tibre","t":"fleuve","km":405,"bassin":17375,"debit":239,"emb":"mer Tyrrhénienne","bref":["Avec une longueur de 405 km, le Tibre (Tevere en italien ; Tiberis en latin) est le troisième plus long fleuve d'Italie après le Pô et l'Adige et le plus long de la péninsule italienne. Il prend sa source dans les Apennins, traverse Rome, capitale italienne, et se jette dans la mer Tyrrhénienne juste à l'ouest de la ville."],"src":"https://fr.vikidia.org/wiki/Tibre","sw":"v","q":"Q13712","pays":["IT"],"c":["europe"]},"tigre":{"n":"Tigre","t":"rivière","km":1850,"bassin":375000,"debit":1014,"src2":"lac Hazar","emb":"Chatt-el-Arab","bref":["Le Tigre est un fleuve de Mésopotamie, long de 1 900 km. Prenant sa source en Turquie, il a momentanément une rive en Syrie et l'autre en Turquie, avant de pénétrer en Irak qu'il ne quittera plus."],"src":"https://fr.vikidia.org/wiki/Tigre_(fleuve)","sw":"v","q":"Q35591","pays":["IQ","SY","TR"],"c":["asie","europe"]},"tisza":{"n":"Tisza","t":"rivière","km":966,"bassin":153200,"debit":796,"src2":"Rakhiv","emb":"Danube","bref":["La Tisza (du hongrois : Tisza [ˈtisɒ], en slovaque et en roumain : Tisa, en allemand : Theiß, en serbe et en ukrainien : Тиса/Tysa, dans les sources anciennes en français : Theisse ou Teysse ou Tibisque est une rivière d'Europe centrale et un affluent du Danube, deuxième fleuve du continent."],"src":"https://fr.wikipedia.org/wiki/Tisza","sw":"w","q":"Q134350","pays":["RO","HU","SK","RS","UA"],"c":["europe"]},"toungouska-inferieure":{"n":"Toungouska Inférieure","t":"rivière","km":2989,"bassin":473000,"debit":3680,"src2":"plateau de Sibérie centrale","emb":"Ienisseï","bref":["La Toungouska Inférieure (en russe : Нижняя Тунгуска, Nijniaïa Toungouska) est une rivière de Russie et un affluent de l'Ienisseï. Son cours long de 2 989 km est entièrement situé en Sibérie."],"src":"https://fr.wikipedia.org/wiki/Toungouska_Inf%C3%A9rieure","sw":"w","q":"Q26428","pays":["RU"],"c":["asie","europe"]},"vilioui":{"n":"Viliouï","t":"rivière","km":2650,"bassin":454000,"debit":1468,"src2":"plateau de Sibérie centrale","emb":"Léna","bref":["Le Viliouï ou la Vilyouï (en russe : Вилюй) est une rivière longue de 2 650 km située dans l'est de la Sibérie en Russie d'Asie. C'est le plus long des affluents de la Léna."],"src":"https://fr.wikipedia.org/wiki/Viliou%C3%AF","sw":"w","q":"Q26433","pays":["RU"],"c":["asie","europe"]},"vistule":{"n":"Vistule","t":"fleuve","km":1047,"bassin":194500,"debit":1080,"src2":"Barania Góra","emb":"baie de Gdańsk","bref":["La Vistule (en polonais Wisła) est un fleuve traversant la Pologne. Il constitue le principal fleuve du pays avec l'Oder. Il prend sa source en Haute-Silésie à l'extrême-sud du pays, parcourt la Pologne du sud au nord et termine son cours en se jetant dans la mer Baltique, près de Gdańsk. Son bassin versant représente 60 % de la superficie de la Pologne."],"src":"https://fr.vikidia.org/wiki/Vistule","sw":"v","q":"Q548","pays":["PL"],"c":["europe"]},"vltava":{"n":"Vltava","t":"rivière","km":430,"bassin":28000,"debit":150,"src2":"forêt de Bohême","emb":"Elbe","bref":["La Moldau est la plus longue rivière de Tchéquie et arrose notamment sa capitale Prague avant de se jeter dans l'Elbe.","Souvent considérée comme un symbole de la Tchéquie, elle a inspiré le mouvement La Moldau ou Vltava du poème symphonique Má Vlast de Bedřich Smetana."],"src":"https://fr.wikipedia.org/wiki/Moldau","sw":"w","q":"Q131574","pays":["CZ"],"c":["europe"]},"volga":{"n":"Volga","t":"fleuve","km":3530,"bassin":1360000,"debit":8060,"src2":"Collines de Valdaï","emb":"mer Caspienne","bref":["La Volga (en russe : Волга) est le plus grand fleuve d'Europe. Elle est longue de 3690 km et occupe un bassin de 1 360 000 km², qui représente les deux cinquièmes de la Russie d'Europe et où vit la moitié de la population russe. Son importance économique, culturelle et historique, sa longueur et la superficie de son bassin en font un fleuve très important dont la célébrité à largement dépassé les frontières de la Russie."],"src":"https://fr.vikidia.org/wiki/Volga","sw":"v","q":"Q626","pays":["RU"],"c":["asie","europe"]},"volta":{"n":"Volta","t":"fleuve","km":1500,"bassin":388000,"debit":1288,"emb":"golfe de Guinée","bref":["La Volta est un fleuve d'Afrique de l'Ouest qui se jette dans le golfe de Guinée. Elle est formée par la confluence de la Volta Noire (aujourd'hui Mouhoun), la Volta Blanche (aujourd'hui Nakambé) et la Volta Rouge (aujourd'hui Nazinon). Ce fleuve donna autrefois son nom au pays de la Haute-Volta, avant qu'il prenne le nom de Burkina Faso en 1984.","Le lac Volta, le plus grand lac artificiel du monde, s'étend du barrage d'Akosombo au sud-est du Ghana, jusqu'à la ville de Yapei, à 520 kilomètres au nord. Ce lac et ce barrage produisent de l'électricité, permettent le transport fluvial, et sont une ressource potentielle pour l'irrigation et la pisciculture."],"src":"https://fr.wikipedia.org/wiki/Volta_(fleuve)","sw":"w","q":"Q192415","pays":["GH","BF"],"c":["afrique"]},"xi-jiang":{"n":"Xi Jiang","t":"rivière","km":2197,"bassin":437000,"debit":7410,"emb":"rivière des Perles","bref":["Le Xi (chinois : 西江 ; pinyin : xī jiāng ; pinyin postal : si kiang ; littéralement : fleuve de l'ouest ; parfois appelé « fleuve Hsi ») est un fleuve du sud de la Chine."],"src":"https://fr.wikipedia.org/wiki/Xi_(fleuve)","sw":"w","q":"Q216941","pays":["CN"],"c":["asie"]},"yamuna":{"n":"Yamunâ","t":"rivière","km":1376,"bassin":351000,"debit":3480,"emb":"Gange","bref":["La Yamuna (en hindi: यमुना (Yamunā) ou जमुना (Jamunā), en ourdou: یمنا (Yamunā) ou جمنا (Jamunā)) — également appelée Jumna, Jamna ou Yamna dans les dialectes locaux — est une rivière majeure de l'Inde, d'une longueur de 1 370 kilomètres, affluent du Gange. La Yamuna est l'une des sept rivières sacrées de l'Inde, mais c'est aussi un des cours d'eau les plus pollués du monde."],"src":"https://fr.wikipedia.org/wiki/Yamuna","sw":"w","q":"Q132726","pays":["IN"],"c":["asie"]},"yangzi-jiang":{"n":"Yangzi Jiang","t":"fleuve","km":6300,"bassin":1808500,"debit":31900,"src2":"plateau tibétain","emb":"mer de Chine orientale","bref":["Le Yangtsé, Yang-Tsé-Kiang ou Yangzi Jiang (en chinois : 扬子江 ; pinyin : Yángzǐjiāng, ou : 长江, Chángjiāng) et également en français fleuve Bleu (par opposition au fleuve Jaune, l'autre grand fleuve chinois, plus au nord), est le plus important des fleuves de Chine et d'Asie avec un débit moyen de 30 000 m3/s et une longueur de 6 380 km. C'est le troisième fleuve du monde par sa longueur après le Nil et l'Amazone, ainsi que par son débit après l'Amazone et le Congo. Ce n'est que le dixième fleuve pour la superficie de son bassin versant, mais celui-ci est le plus peuplé. Il est le plus important au monde à couler entièrement dans un seul pays.","Le Yangtsé prend sa source dans l'Ouest du pays sur le plateau tibétain, dans une région aride et dépourvue d'habitants à plus de 5 300 m d'altitude. Son cours prend d'abord une orientation sud-est et il descend du plateau de manière torrentielle en circulant dans des gorges profondes creusées dans les monts Hengduan. À près de 2 000 km de sa source, le Yangtsé arrive aux abords du plateau Yunnan-Guizhou et prend une direction générale ouest-est qu'il va conserver jusqu'à son débouché dans la mer de Chine orientale."],"src":"https://fr.wikipedia.org/wiki/Yangts%C3%A9","sw":"w","q":"Q5413","pays":["CN"],"c":["asie"]},"yarlung-tsangpo":{"n":"Yarlung Tsangpo","t":"rivière","km":2840,"src2":"Matsang Tsangpo","emb":"Gange","bref":["Le Brahmapoutre[réf. à confirmer] — du sanskrit ब्रह्मपुत्र (Brahmaputra) signifiant « fils de Brahmâ » — est un fleuve de l'Asie du Sud, long de 2 900 km, ayant sa source principale dans l'Himalaya tibétain, à 5 542 m d'altitude, au glacier Gyima Yangzoin, dans le xian de Zhongba (29° 17′ 41″ N, 83° 46′ 23″ E). D'autres sources sont situées au pied des glaciers des monts Kubi-gangri et Ganglung-gangri. C'est le Dyardanes ou l’Œdanes des Grecs anciens. Son parcours tropical fait de la vallée de ce fleuve un des plus riches sites mondiaux au regard de la biodiversité.","Ses crues importantes permettent une fertilisation du sol mais sont dévastatrices. Dans son cours inférieur, qui est sacré pour les Hindous, le fleuve est utilisé pour le transport de produits agricoles. Le Brahmapoutre se jette dans le Padma (nommé Gange en Inde) qui lui-même se jette dans le Meghna. Tous trois (bassin du Gange, bassin du Brahmapoutre et Meghna) forment le bassin Gange-Brahmapoutre-Meghna."],"src":"https://fr.wikipedia.org/wiki/Brahmapoutre","sw":"w","q":"Q3244259","pays":["CN"],"c":["asie"]}},
"lacs":{"cerne-jezero":{"n":"Černé jezero","t":"lac","km2":0,"bref":["Černé jezero (Lac Noir) est le plus grand et le plus profond des lacs naturels de la République tchèque.","De forme triangulaire, ce lac couvrant une superficie d'environ 0,18 km2 est situé à 6 km au nord-ouest de Železná Ruda, dans la région de Plzeň, proche de la frontière allemande. Il s'est formé pendant l'ère glaciaire, lors de la glaciation de Würm. La plus ancienne centrale hydroélectrique de la République tchèque (construite en 1930) se trouve en bordure du lac, dont il compose le réservoir supérieur."],"src":"https://fr.wikipedia.org/wiki/%C4%8Cern%C3%A9_jezero","sw":"w","q":"Q45642","pays":["CZ"],"c":["europe"]},"crater-lake":{"n":"Crater Lake","t":"lac","km2":53,"bref":["Crater Lake est un lac occupant une ancienne caldeira située dans l’Oregon, au sein de la chaîne des Cascades, dans l’Ouest des États-Unis. Comme les volcans Rainier et St. Helens, cet ancien volcan appartient à l'arc volcanique des Hautes Cascades.","Le site se situe à 185 kilomètres à l'est-sud-est des plages d'Hauser, sur l'océan Pacifique et â 84 kilomètres au nord-nord-ouest de Klamath Falls."],"src":"https://fr.vikidia.org/wiki/Crater_Lake","sw":"v","q":"Q329266","pays":["US"],"c":["amerique-nord"]},"grand-lac-de-l-ours":{"n":"Grand Lac de l'Ours","t":"lac","km2":31153,"bref":["Le grand lac de l'Ours est un lac du Canada, situé dans les Territoires du Nord-Ouest, plus précisément dans la région administrative de Sahtu (en anglais Sahtu Lands)."],"src":"https://fr.vikidia.org/wiki/Grand_lac_de_l'Ours","sw":"v","q":"Q5525","pays":["CA"],"c":["amerique-nord"]},"konigssee":{"n":"Königssee","t":"lac","km2":5,"bref":["Le Königssee est un lac alpin dans le Sud-Est de la Bavière, dans le Pays-de-Berchtesgaden, non loin de la commune de Schönau am Königssee. De forme rectangulaire, il est situé au pied du chaînon du Watzmann à la manière d'un fjord, entouré de hautes montagnes des Alpes de Berchtesgaden. Au sud du Königssee se trouve l'Obersee, qui est seulement de quelques mètres plus élevé.","Pendant la dernière glaciation, ce lac profond s'est formé par les mouvements des glaciers et était retenu par un barrage naturel à son écoulement. La conservation de la beauté du lac et de sa rive sont à l'origine du parc national de Berchtesgaden qui englobe une grande partie. Le lac lui-même est administré par la Bayerische Schlösserverwaltung de l'État de Bavière."],"src":"https://fr.wikipedia.org/wiki/K%C3%B6nigssee","sw":"w","q":"Q156715","pays":["DE"],"c":["europe"]},"lac-albert":{"n":"lac Albert","t":"lac","km2":5270,"bref":["Le lac Albert est un lac partagé par l'Ouganda et la république démocratique du Congo. C'est l'un des grands lacs africains, le septième lac d'Afrique par la superficie et l'un des plus riches au monde en poissons.","Ses autres noms sont Albert Nyanza, M'vouta-N'zighé et Mwitanzige en langues bantoues, et anciennement lac Mobutu Sese Seko."],"src":"https://fr.wikipedia.org/wiki/Lac_Albert","sw":"w","q":"Q125888","pays":["UG","CD"],"c":["afrique"]},"lac-athabasca":{"n":"Lac Athabasca","t":"lac","km2":7850,"bref":["Le lac Athabasca se situe à la frontière nord des provinces canadiennes de la Saskatchewan et de l'Alberta, entre le 58° et le 60° N."],"src":"https://fr.wikipedia.org/wiki/Lac_Athabasca","sw":"w","q":"Q272463","pays":["CA"],"c":["amerique-nord"]},"lac-baikal":{"n":"lac Baïkal","t":"lac","km2":31722,"bref":["Le lac Baïkal (en russe, Озеро Байкал) est un lac de Russie, situé au nord de la Mongolie. Ce lac est classé au patrimoine mondial de l'UNESCO depuis 1996."],"src":"https://fr.vikidia.org/wiki/Lac_Ba%C3%AFkal","sw":"v","q":"Q5513","pays":["RU","MN"],"c":["asie","europe"]},"lac-balaton":{"n":"lac Balaton","t":"lac","km2":592,"bref":["Le lac Balaton (en allemand Plattensee, le hongrois dit simplement a Balaton, « le Balaton ») est un lac d'eau douce, le plus grand d'Europe centrale, situé à environ une centaine de km au Sud-Ouest de Budapest (pour sa partie la plus septentrionale). Orienté selon un axe Nord-Est / Sud-Ouest, il est de forme allongée comme le lac Léman mais n'est pas courbé comme ce dernier. Légèrement plus grand que le lac Léman, il est nettement moins profond et son volume est 45 fois plus faible. En effet, sa profondeur moyenne est inférieure à 3,5 m et sa profondeur maximale seulement 12,5 m.","Du fait de sa taille, il a une certaine influence sur le climat de la région, similaire à l’effet modérateur de la mer : les écarts de températures entre l'hiver et l'été sont moins prononcés, parce que l'eau se réchauffe et se refroidit plus lentement que la terre, et les précipitations sont plus importantes. Les hivers restent cependant suffisamment froids pour que ce lac gèle en hiver."],"src":"https://fr.vikidia.org/wiki/Lac_Balaton","sw":"v","q":"Q6383","pays":["HU"],"c":["europe"]},"lac-balkhach":{"n":"lac Balkhach","t":"lac","km2":18200,"bref":["Le lac Balkhach est un lac endoréique situé au Kazakhstan, à 260 kilomètres au nord-ouest d'Almaty, la plus grande ville du pays et à 569 kilomètres au sud-sud-est d'Astana, la capitale. Il est situé à 342 mètres d'altitude au nord de l'Issyk-Koul, un lac isolé de l'océan et situé dans le Tian Shan.","Le lac Balkhach a une longueur de 578 kilomètres. Sa surface est variable selon le régime hydrique : elle peut atteindre environ 18 500 kilomètres carrés en période de pluies comme elle peut se réduire en période de sécheresse à une valeur comprise entre 15 500 et 16 500 kilomètres carrés. Ces variations ont une incidence sur le niveau qui varie de trois mètres entre les saisons humide et sèche."],"src":"https://fr.vikidia.org/wiki/Lac_Balkhach","sw":"v","q":"Q134485","pays":["KZ"],"c":["asie","europe"]},"lac-bangwelo":{"n":"lac Bangwelo","t":"lac","km2":9840,"bref":["Le lac Bangwelo (aussi orthographié Bangweule ou Bangweolo) est un lac d’eau douce peu profond situé dans le nord-est de la Zambie il forme avec les marécages de Bangwelo et la plaine inondable qui l'entourent l'un de plus grands système de zones humides d'Afrique. Alimenté par 17 rivières, dont la Chambeshi au nord, il est la source de la Luapula, qui traverse le lac Moero avant de rejoindre le fleuve Congo. Son nom signifie \"le lieu où l'eau et le ciel se rejoignent\"."],"src":"https://fr.wikipedia.org/wiki/Lac_Bangwelo","sw":"w","q":"Q673169","pays":["ZM"],"c":["afrique"]},"lac-bogoria":{"n":"lac Bogoria","t":"lac","km2":34,"bref":["Le lac Bogoria est un lac de soude, salé qui se trouve dans la région volcanique du bassin du lac Baringo au Kenya. Il abrite régulièrement une des plus importantes colonies de flamants nains au monde. Il est classé site Ramsar depuis le 27 août 2001."],"src":"https://fr.wikipedia.org/wiki/Lac_Bogoria","sw":"w","q":"Q890651","pays":["KE"],"c":["afrique"]},"lac-champlain":{"n":"lac Champlain","t":"lac","km2":1269,"bref":["Le lac Champlain (en anglais : Lake Champlain ; en abénaqui : Pitawbagok ; en mohawk : Kaniatarakwà:ronte) est un grand lac frontalier du Canada et des États-Unis. Son étendue se situe essentiellement sur le territoire des États américains du Vermont et de New York, ses deux extrémités nord se trouvant sur celui de la province canadienne de Québec. D'une superficie de 1 269 km2, il forme la sixième plus grande étendue d'eau des États-Unis."],"src":"https://fr.wikipedia.org/wiki/Lac_Champlain","sw":"w","q":"Q68467","pays":["US","CA"],"c":["amerique-nord"]},"lac-d-iseo":{"n":"lac d'Iseo","t":"lac","km2":65,"bref":["Le lac d'Iseo (en italien : Lago d'Iseo ou Sebino) est un lac des préalpes italiennes. Avec une superficie de 65 km², placé au fond du Val Camonica, situé en Lombardie, il contient la plus grande île lacustre d’Europe, Monte Isola."],"src":"https://fr.wikipedia.org/wiki/Lac_d'Iseo","sw":"w","q":"Q15648","pays":["IT"],"c":["europe"]},"lac-d-ohrid":{"n":"lac d'Ohrid","t":"lac","km2":349,"bref":["Le lac d'Ohrid est un lac situé en Europe du Sud-Est, à la frontière entre la Macédoine du Nord et l’Albanie. C’est l’un des plus vieux et des plus profonds lacs d’Europe."],"src":"https://fr.vikidia.org/wiki/Lac_d'Ohrid","sw":"v","q":"Q156258","pays":["MK","AL"],"c":["europe"]},"lac-de-bled":{"n":"lac de Bled","t":"lac","km2":1,"bref":["Le lac de Bled (en slovène : Blejsko jezero ; en allemand : Veldeser See) est un lac d'origine glaciaire en Slovénie. Situé dans la région de Haute-Carniole à 55 kilomètres au nord-ouest du centre de la capitale Ljubljana, en bordure orientale des Alpes juliennes, c'est l'une des principales destinations touristiques du pays."],"src":"https://fr.wikipedia.org/wiki/Lac_de_Bled","sw":"w","q":"Q648902","pays":["SI"],"c":["europe"]},"lac-de-chiem":{"n":"lac de Chiem","t":"lac","km2":80,"bref":["Le Chiemsee, parfois appelé en français lac de Chiem, surnommé « la mer bavaroise »[réf. nécessaire], est un lac d'Allemagne situé dans le land de Bavière. Avec une superficie de 80 km2, c'est le plus grand lac de ce land et le troisième plus grand d'Allemagne. Il a été reconnu comme site Ramsar en 1976, en raison de son intérêt ornithologique.","La partie Sud du lac comporte trois îles, qui constituent le territoire de la commune de Chiemsee. Le roi de Bavière Louis II a fait construire un château sur l'île Herrenchiemsee, la plus méridionale."],"src":"https://fr.wikipedia.org/wiki/Chiemsee","sw":"w","q":"Q4138","pays":["DE"],"c":["europe"]},"lac-de-garde":{"n":"lac de Garde","t":"lac","km2":370,"bref":["Le lac de Garde (en italien : lago di Garda ou lago Benaco) est un lac des Alpes italiennes. Avec une superficie de 367 km2 et une profondeur maximale de 346 mètres, il est le plus grand lac d'Italie."],"src":"https://fr.wikipedia.org/wiki/Lac_de_Garde","sw":"w","q":"Q6414","pays":["IT"],"c":["europe"]},"lac-de-l-ouest":{"n":"lac de l'Ouest","t":"lac","km2":7,"bref":["Le lac de l'Ouest (Hồ Tây en vietnamien) est le plus grand lac naturel de la ville de Hanoï, au Vietnam. Il s'étend sur plus de 500 hectares et sa circonférence est de 18 kilomètres."],"src":"https://fr.vikidia.org/wiki/Lac_de_l'Ouest","sw":"v","q":"Q502371","pays":["CN"],"c":["asie"]},"lac-de-lugano":{"n":"lac de Lugano","t":"lac","km2":49,"bref":["Le lac de Lugano (en italien : lago di Lugano ou lago Ceresio) est un lac glaciaire partagé entre le Canton du Tessin en Suisse et la Lombardie en Italie. Le lac, nommé d'après la ville de Lugano, est situé entre le lac de Côme et le lac Majeur. Les montagnes et les destinations touristiques connues sur les rives du lac sont Monte Brè à l'est, le Monte San Salvatore à l'ouest de Lugano et le Monte Generoso sur la rive sud-est. Le site du patrimoine mondial, Monte San Giorgio, est situé au sud du lac."],"src":"https://fr.wikipedia.org/wiki/Lac_de_Lugano","sw":"w","q":"Q14418","pays":["CH","IT"],"c":["europe"]},"lac-de-neuchatel":{"n":"lac de Neuchâtel","t":"lac","km2":218,"bref":["Le lac de Neuchâtel (en allemand Neuenburgersee) est le plus grand lac entièrement suisse.","Le lac de Neuchâtel est situé au pied du Jura, sur le plateau suisse.","Le lac de Neuchâtel fait 38 km de long et a une largeur maximale de 8,2 km. La superficie est de près de 218 km2. Sa profondeur maximale est de 152 m et sa capacité est estimée à 14 km3.","Le lac est alimenté par la Thièle, l'Arnon, le Sayon, la Mentue et le canal de la Broye qui lui apporte les eaux du lac de Morat. Il se déverse dans le lac de Bienne par le canal de la Thielle (Zihlkanal).","Le fond du lac est exploité pour fournir du gravier. On y pratique la pêche (environ 324 tonnes chaque année). La navigation de plaisance est développée grâce aux villes touristiques qui le bordent. Le lac est un site d'observation pour les espèces d'oiseaux aquatiques."],"src":"https://fr.vikidia.org/wiki/Lac_de_Neuch%C3%A2tel","sw":"v","q":"Q14375","pays":["CH"],"c":["europe"]},"lac-de-skadar":{"n":"lac de Skadar","t":"lac","km2":530,"bref":["Le lac de Shkodër (en albanais : Liqeni i Shkodrës) ou lac Skadar (en monténégrin : Skadarsko jezero), parfois appelé sous son nom italien lac de Scutari (en italien : Lago di Scutari) est le plus grand lac d'Europe du Sud. Situé à la frontière du Monténégro et de l'Albanie, il doit son nom à la ville albanaise de Shkodër."],"src":"https://fr.wikipedia.org/wiki/Lac_de_Shkod%C3%ABr","sw":"w","q":"Q203811","pays":["AL","ME"],"c":["europe"]},"lac-de-starnberg":{"n":"lac de Starnberg","t":"lac","km2":56,"bref":["Le lac de Starnberg (en allemand : Starnberger See) est un lac d'Allemagne situé dans le land de Bavière et le district de Haute-Bavière.","C'est le cinquième lac d'Allemagne par la superficie (56 km2).","La douceur de son climat et la beauté des paysages en fait depuis 1880 un lieu de villégiature apprécié des riches Munichois.","Élisabeth de Wittelsbach, dite « Sissi », épouse à partir de 1854 de l'empereur d'Autriche François-Joseph, a passé son enfance au château de Possenhofen situé sur la rive Ouest du lac.","C'est aussi dans ce lac qu'est mort noyé le roi de Bavière Louis II, cousin de Sissi, en 1886."],"src":"https://fr.wikipedia.org/wiki/Lac_de_Starnberg","sw":"w","q":"Q131615","pays":["DE"],"c":["europe"]},"lac-de-zurich":{"n":"lac de Zurich","t":"lac","km2":89,"bref":["Le lac de Zurich (en allemand Zürichsee, en zurichois Zürisee) est un lac suisse qui se trouve au sud-est de la ville de Zurich. Il est bordé par les cantons de Zurich, Schwytz et Saint-Gall."],"src":"https://fr.wikipedia.org/wiki/Lac_de_Zurich","sw":"w","q":"Q14407","pays":["CH"],"c":["europe"]},"lac-des-quatre-cantons":{"n":"lac des Quatre-Cantons","t":"lac","km2":114,"bref":["Le lac des Quatre-Cantons est un lac de la Suisse centrale. C'est un lac d'origine glaciaire.","Le lac des Quatre-Cantons mesure 38 km de long. Il s'étend sur 114 km2. Sa surface est à 434 m au-dessus du niveau de la mer. Il atteint 214 m de profondeur.","Le lac des Quatre-Cantons s'appelle le Viderwaldstättersee en allemand, Lago dei Quattro Cantoni et lago di Lucerna en italien et Lai dals Quatter Chantung en romanche.","Le mot Waldstätten désigne les trois cantons d'Uri, de Schwytz et Nidwald qui en s'unissant en 1291 sont à l'origine de la Confédération helvétique. Ils furent rejoints par le canton de Lucerne en 1332."],"src":"https://fr.vikidia.org/wiki/Lac_des_Quatre-Cantons","sw":"v","q":"Q14381","pays":["CH"],"c":["europe"]},"lac-dongting":{"n":"lac Dongting","t":"lac","km2":4350,"bref":["Le lac Dongting (chinois : 洞庭湖 ; pinyin : dòngtíng hú), lac Dongting-hu ou lac Dong est le premier grand lac de Chine, dans la province du Hunan."],"src":"https://fr.wikipedia.org/wiki/Lac_Dongting","sw":"w","q":"Q216083","pays":["CN"],"c":["asie"]},"lac-edouard":{"n":"lac Édouard","t":"lac","km2":2150,"bref":["Le lac Édouard (lac Mutsyamira) est un des Grands Lacs d'Afrique. Il se trouve dans la vallée du Grand Rift, sur la frontière entre la république démocratique du Congo (qui possède 71 % de sa surface) et l'Ouganda (29 %)."],"src":"https://fr.wikipedia.org/wiki/Lac_%C3%89douard","sw":"w","q":"Q125211","pays":["UG","CD"],"c":["afrique"]},"lac-erie":{"n":"lac Érié","t":"lac","km2":25744,"bref":["Le lac Érié est l'un des cinq Grands Lacs d'Amérique du Nord. C'est le lac le plus au sud. Il sert de frontière entre les États-Unis (Ohio, Pennsylvanie, New York) et le Canada (province de l'Ontario)."],"src":"https://fr.vikidia.org/wiki/Lac_%C3%89ri%C3%A9","sw":"v","q":"Q5492","pays":["CA","US"],"c":["amerique-nord"]},"lac-eyre":{"n":"lac Eyre","t":"lac","km2":9300,"bref":["Le lac Eyre, officiellement Kati Thanda–Lake Eyre, est le plus grand lac salé d'Australie et d'Océanie avec une superficie de 9 300 km2. Il est également le point le plus bas de l'Australie à approximativement 13 mètres en dessous du niveau de la mer et représente le point central du vaste bassin du lac Eyre. Le lac est situé dans les déserts du centre de l'Australie, au nord de Port Augusta dans la partie septentrionale de l'État d'Australie-Méridionale. Il est souvent asséché et se remplit une fois tous les quinze à vingt ans environ lors de pluies diluviennes."],"src":"https://fr.wikipedia.org/wiki/Lac_Eyre","sw":"w","q":"Q179970","pays":["AU"],"c":["oceanie"]},"lac-huron":{"n":"lac Huron","t":"lac","km2":59600,"bref":["Le lac Huron est l'un des cinq Grands Lacs d'Amérique du Nord, sur la frontière entre les États-Unis et le Canada. Il est le deuxième des Grands Lacs par la superficie qui atteint 59 600 kilomètres carrs. Sa longueur est de 438 kilomètres et sa largeur maximale de 246 kilomètres."],"src":"https://fr.vikidia.org/wiki/Lac_Huron","sw":"v","q":"Q1383","pays":["CA","US"],"c":["amerique-nord"]},"lac-ilmen":{"n":"lac Ilmen","t":"lac","km2":982,"bref":["Le lac Ilmen (en russe : Озеро Ильмень, en finnois : Ilmajärvi) est un lac de l'oblast de Novgorod, en Russie. Le lac Ilmen avec son émissaire, la Volkhov forme un bassin hydrographique de 80 200 km2, par ailleurs sous-bassin du bassin du Lac Ladoga."],"src":"https://fr.wikipedia.org/wiki/Lac_Ilmen","sw":"w","q":"Q203462","pays":["RU","BY"],"c":["asie","europe"]},"lac-inari":{"n":"lac Inari","t":"lac","km2":1082,"bref":["Le lac Inari, en finnois Inarijärvi, en same d'Inari Aanaarjävri, en same du Nord Anárjávri, est un lac finlandais situé dans la province et région de Laponie, dans la commune d'Inari."],"src":"https://fr.wikipedia.org/wiki/Lac_Inari","sw":"w","q":"Q203137","pays":["FI"],"c":["europe"]},"lac-khanka":{"n":"lac Khanka","t":"lac","km2":4190,"bref":["Le lac Khanka ou lac Xingkai est un lac d’eau douce à la frontière entre la province chinoise de Heilongjiang et le kraï du Primorie, en Russie. L’eau du lac est tellement limpide et le ciel de cette région tellement bleu, qu’on a appelé ce lac « l’émeraude du Nord »."],"src":"https://fr.wikipedia.org/wiki/Lac_Khanka","sw":"w","q":"Q201843","pays":["RU","CN"],"c":["asie","europe"]},"lac-kivu":{"n":"lac Kivu","t":"lac","km2":2700,"bref":["Le lac Kivu (2 700 km2), situé à la frontière de la république démocratique du Congo et du Rwanda, est l'un des Grands Lacs d'Afrique. Il est le plus dangereux des trois lacs méromictiques du continent, car contenant de grandes quantités de gaz toxique, asphyxiant et à effet de serre (sulfure d'hydrogène, gaz carbonique et méthane). Il pourrait brutalement dégazer en cas de tremblement de terre."],"src":"https://fr.wikipedia.org/wiki/Lac_Kivu","sw":"w","q":"Q125912","pays":["CD","RW"],"c":["afrique"]},"lac-ladoga":{"n":"lac Ladoga","t":"lac","km2":17700,"bref":["Le lac Ladoga (en russe : Ладожское озеро) est un lac de Russie occidentale.","C'est le plus grand lac d'Europe (17 700 km²), le deuxième lac de Russie, après le lac Baïkal, et le 15e du monde par sa superficie. La partie sud-ouest du lac dépend de l'oblast de Léningrad, celle du nord-est se trouve en république de Carélie. Il se situe à trente-neuf kilomètres à l'est de Saint-Pétersbourg. Sa longueur nord-sud s'élève à 202 kilomètres et sa largeur maximale est de 122 kilomètres.","Il est alimenté par une trentaine de rivières dont le Vuoksi et le Svir, ce dernier étant en même temps l'émissaire du lac Onega, c'est-à-dire la rivière par où s'écoulent les eaux de ce lac. Le lac Ladoga a lui-même un émissaire qui lui permet de rester à niveau constant : c'est la rivière Néva qui traverse la ville de Saint-Pétersbourg et se jette dans la mer Baltique."],"src":"https://fr.vikidia.org/wiki/Lac_Ladoga","sw":"v","q":"Q15288","pays":["RU","FI"],"c":["asie","europe"]},"lac-mackay":{"n":"lac Mackay","t":"lac","km2":4737,"bref":["Le lac Mackay est le quatrième plus grand lac d'Australie. Situé sur la frontière entre l'Australie-Occidentale et le Territoire du Nord, il est un lac salé et a une superficie de 3 494 km2.","Il est situé au cœur du Grand Désert de Sable, au nord-est du désert de Gibson et au sud-ouest du désert de Tanami."],"src":"https://fr.wikipedia.org/wiki/Lac_Mackay","sw":"w","q":"Q1074063","pays":["AU"],"c":["oceanie"]},"lac-majeur":{"n":"lac Majeur","t":"lac","km2":213,"bref":["Le lac Majeur (Lago Maggiore ou Verbano, en italien, à cause de la verveine qui colonisait son rivage) est un lac préalpin italo-suisse de 212 km2 et 65 km de longueur, à environ 50 km au nord-ouest de Milan, à cheval sur le Piémont, la Lombardie et le canton du Tessin. Haut lieu touristique suisse-italien, il est baptisé Majeur car il est un des lacs les plus importants de la région (lac le plus important d'Italie après le lac de Garde)."],"src":"https://fr.wikipedia.org/wiki/Lac_Majeur","sw":"w","q":"Q14379","pays":["CH","IT"],"c":["europe"]},"lac-malar":{"n":"lac Mälar","t":"lac","km2":1072,"bref":["Le lac Mälar (en suédois : Mälaren) est, par sa taille, le troisième lac de Suède (après le Vänern et le Vättern), avec une étendue de 1 140 km2 et un volume de 14 km3."],"src":"https://fr.wikipedia.org/wiki/Lac_M%C3%A4lar","sw":"w","q":"Q184492","pays":["SE"],"c":["europe"]},"lac-malawi":{"n":"lac Malawi","t":"lac","km2":29600,"bref":["Le lac Malawi est un lac situé en Afrique. Il fait partie des Grands Lacs d'Afrique qui se sont formés grâce au rift est-africain. Parmi ces lacs il est celui situé le plus au sud et il est le troisième par la taille après le lac Victoria et le lac Tanganyika."],"src":"https://fr.vikidia.org/wiki/Lac_Malawi","sw":"v","q":"Q5532","pays":["MW","MZ","TZ"],"c":["afrique"]},"lac-managua":{"n":"lac Managua","t":"lac","km2":1042,"bref":["Le lac de Managua (également connu comme lac Xolotlán en nahuat ou lago de Managua en espagnol) est un lac situé au Nicaragua.","C'est le deuxième plus grand lac d'eau douce d'Amérique centrale et le deuxième plus grand lac du pays après le lac Cocibloca.","Il occupe en Amérique Latine le troisième rang pour sa superficie se situant après le Lac Nicaragua et le Lac de Chapala qui se trouve au Mexique."],"src":"https://fr.wikipedia.org/wiki/Lac_de_Managua","sw":"w","q":"Q272380","pays":["NI"],"c":["amerique-nord"]},"lac-manasarovar":{"n":"lac Manasarovar","t":"lac","km2":395,"bref":["Le lac Manasarovar (du sanskrit : मानस सरोवर, Manasa Sarovar, translittéré en chinois : 玛那萨罗瓦 ; pinyin : mǎnàsàluówǎ), ou Mapam Yumco (tibétain : མ་ཕམ་གཡུ་མཚོ་, Wylie : Ma-pham g.yu-mtsho), translittéré en chinois : 玛旁雍错 ; pinyin : mǎpáng yōngcuò), est un lac d'eau douce de la région autonome du Tibet en Chine, considéré comme un lieu sacré à la fois au Tibet et en Inde. Il est situé dans la préfecture de Ngari, à plus de 1 600 km à l'ouest de Lhassa. Il est séparé du lac Rakshastal, son proche voisin occidental, par une bande de terre de seulement quelques kilomètres de largeur, et est surplombé par le mont Kailash, une trentaine de kilomètres plus au nord."],"src":"https://fr.wikipedia.org/wiki/Lac_Manasarovar","sw":"w","q":"Q233627","pays":["CN"],"c":["asie"]},"lac-manitoba":{"n":"lac Manitoba","t":"lac","km2":4624,"bref":["Le lac Manitoba est un vaste lac d'eau saumâtre d’origine glaciaire d’environ 4 624 km2 situé en Amérique du Nord, dans la province canadienne du Manitoba, à 75 kilomètres au nord-ouest de la ville de Winnipeg. Il tire son nom du cri manitou-wapow ou de l'ojibwé manitou-bah signifiant « le détroit de Manitou, le Grand Esprit », toponyme qui correspond à ce qui est appelé de nos jours The Narrows au centre du lac."],"src":"https://fr.wikipedia.org/wiki/Lac_Manitoba","sw":"w","q":"Q645901","pays":["CA"],"c":["amerique-nord"]},"lac-maracaibo":{"n":"lac Maracaibo","t":"lac","km2":13210,"bref":["Le lac de Maracaibo (en espagnol lago de Maracaibo) est une vaste étendue d'eau saumâtre située dans le Nord-Ouest du Venezuela. Il se situe dans une plaine côtière définie par l'extrémité nord de la cordillère Orientale au sud-ouest, la serrania de Perijá à l'ouest, la sierra de Mérida au sud-est et la sierra de Baragua à l'est.","La superficie du lac est de 13 280 kilomètres carrés et sa longueur nord-sud de 221 kilomètres pour une largeur maximale de 121 kilomètres."],"src":"https://fr.vikidia.org/wiki/Lac_de_Maracaibo","sw":"v","q":"Q182137","pays":["VE"],"c":["amerique-sud"]},"lac-michigan":{"n":"lac Michigan","t":"lac","km2":57750,"bref":["Le lac Michigan est l'un des cinq Grands Lacs d'Amérique du Nord. Il est le seul à être totalement situé aux États-Unis : il est bordé par quatre États, principalement le Wisconsin à l’Ouest et le Michigan à l’Est et au Nord-Ouest du lac, et un peu l'Illinois et l'Indiana au Sud ; Chicago, de loin la ville la plus grande au bord de ce lac, se situe tout au Sud. Il communique avec le lac Huron par le détroit de Mont-Huron. La troisième ville des États-Unis, Chicago, est située vers le sud sur la rive ouest du lac Michigan, dans l'État américain de l'Illinois. Sur la rive ouest se trouve Milwaukee dand l'État du Wisconsin (États-Unis)."],"src":"https://fr.vikidia.org/wiki/Lac_Michigan","sw":"v","q":"Q1169","pays":["US"],"c":["amerique-nord"]},"lac-moero":{"n":"lac Moero","t":"lac","km2":4650,"bref":["Le lac Moero (aussi écrit lac Mwero ou lac Mweru) est un lac situé à la frontière entre la république démocratique du Congo et la Zambie, à environ 150 kilomètres au sud du lac Tanganyika, au sud des monts Mugita dans le bassin du fleuve Congo."],"src":"https://fr.wikipedia.org/wiki/Lac_Moero","sw":"w","q":"Q504433","pays":["ZM","CD"],"c":["afrique"]},"lac-namtso":{"n":"lac Namtso","t":"lac","km2":1920,"bref":["Le lac Namtso (tibétain : གནམ་མཚོ་, Wylie : gnam mtsho, pinyin tibétain : Nam Co, THL : Namtso, translittération en chinois : 纳木错 ; pinyin : nàmù cuò Nam Co est son nom officiel international en Chine), également appelé en mongol Tangri Nagur ou Tenger nuur (mongol classique et Mongol de Chine : ᠲᠩᠷᠢ ᠨᠠᠭᠤᠷ (Tangri naɣur), khalkha : Тэнгэр нуур (Tenger nuur) littéralement lac céleste), est l'un des lacs les plus célèbres du Tibet.","Il est un lieu saint du bouddhisme tibétain. De nombreux fidèles se réunissent autour du lac pour une grande cérémonie qui s'y déroule l'année du mouton, tous les douze ans. Il abrite également le monastère sur la péninsule de Tashi Dor située à son extrémité sud-est."],"src":"https://fr.wikipedia.org/wiki/Lac_Namtso","sw":"w","q":"Q651294","pays":["CN"],"c":["asie"]},"lac-nettilling":{"n":"lac Nettilling","t":"lac","km2":5051,"bref":["Le lac Nettilling [nech'iling] est un lac d’eau douce situé au sud de l'île de Baffin dans le territoire du Nunavut au Canada. Il se situe sur la grande plaine de Koukdjuak à 280 km au nord d'Iqaluit. Le nom du lac tire probablement son nom du mot « netsilak » qui signifie phoque annelé en inuktitut, et cette espèce y est d'ailleurs présente en petit nombre. La côte sud du lac fut explorée en 1883 par Franz Boas.","Le lac Nettilling est le plus grand lac du Nunavut avec ses 5 542 km2, le 11e plus grand lac du Canada, ainsi que le plus grand lac au monde situé sur une île. Son altitude est de 30 mètres et sa longueur de 123 km. Il est alimenté par le lac Amadjuak, le deuxième plus grand de l'île de Baffin, et par plusieurs autres plus petits lacs. Il se déverse à l’est dans le bassin de Foxe via la rivière Koukdjuak qui est peu profonde."],"src":"https://fr.wikipedia.org/wiki/Lac_Nettilling","sw":"w","q":"Q1132211","pays":["CA"],"c":["amerique-nord"]},"lac-nicaragua":{"n":"lac Nicaragua","t":"lac","km2":8264,"bref":["Le lac Nicaragua est un lac d'eau douce d'Amérique centrale, entièrement situé au Nicaragua."],"src":"https://fr.wikipedia.org/wiki/Lac_Nicaragua","sw":"w","q":"Q173862","pays":["NI"],"c":["amerique-nord"]},"lac-nyos":{"n":"lac Nyos","t":"lac","km2":2,"bref":["Le lac Nyos (en réalité lac Lwi, devenu populaire sous le nom de lac Nyos, Nyos étant le nom du village voisin du lac) est un lac de cratère volcanique situé dans la province du Nord-Ouest du Cameroun. Il est situé à 1 091 mètres d’altitude, sur le flanc d’un volcan inactif près du mont Oku, le long d'une ceinture volcanique longue de 1 400 kilomètres : la Ligne du Cameroun, le mont Cameroun (4 095 mètres) restant le seul volcan en activité de cette chaîne. Un barrage naturel de roches volcaniques piège les eaux du lac.","Le lac a connu le 21 août 1986 une éruption limnique qui a causé la mort de 1 746 personnes dans les villes environnantes."],"src":"https://fr.wikipedia.org/wiki/Lac_Nyos","sw":"w","q":"Q332628","pays":["CM"],"c":["afrique"]},"lac-onega":{"n":"lac Onega","t":"lac","km2":9800,"bref":["Le lac Onega (en russe : Онежское озеро, Onejskoïe ozero ; en finnois/carélien : Ääninen ou Äänisjärvi), également connu sous le nom d'Onego, ou encore d'Oniégo, est le second lac d'Europe par son étendue, après le lac Ladoga.","Le lac Onega, avec son émissaire le Svir, forme un bassin hydrographique de 83 200 km2, par ailleurs sous-bassin du bassin du lac Ladoga."],"src":"https://fr.wikipedia.org/wiki/Lac_Onega","sw":"w","q":"Q166162","pays":["RU"],"c":["asie","europe"]},"lac-ontario":{"n":"lac Ontario","t":"lac","km2":18529,"bref":["Le lac Ontario est l'un des cinq Grands Lacs d'Amérique du Nord, sur la frontière entre les États-Unis et le Canada. C'est le plus oriental des Grands Lacs."],"src":"https://fr.vikidia.org/wiki/Lac_Ontario","sw":"v","q":"Q1062","pays":["CA","US"],"c":["amerique-nord"]},"lac-pangong":{"n":"lac Pangong","t":"lac","km2":690,"bref":["Le lac Pangong (ou Pangong Tso, tibétain : སྤང་གོང་མཚོ།, Wylie : spang gong mtsho) est une vaste étendue d'eau située en marge du plateau tibétain, entre des massifs montagneux périphériques au Karakoram et à la chaîne du Kailash (Gangdise Shan). Il s'élève à une altitude d'environ 4 250 m, et est endoréique, ses eaux salées (lac de soude) ne trouvent pas d'exutoire pour aboutir à l'océan."],"src":"https://fr.wikipedia.org/wiki/Lac_Pangong","sw":"w","q":"Q1032254","pays":["CN","IN"],"c":["asie"]},"lac-peipous":{"n":"lac Peïpous","t":"lac","km2":3543,"bref":["Le lac Peïpous ou lac des Tchoudes (en russe : Псковско-Чудское озеро, Чудско-Псковское озеро, Pskovsko-Tchoudskoïe ozero, Tchoudsko-Pskovskoïe ozero ; en estonien : Peipsi-Pihkva järv ; en allemand : Peipussee) est un vaste lac partagé entre l'Estonie et la Russie."],"src":"https://fr.wikipedia.org/wiki/Lac_Pe%C3%AFpous","sw":"w","q":"Q19253","pays":["EE","RU","LV","BY"],"c":["europe","asie"]},"lac-poopo":{"n":"lac Poopó","t":"lac","km2":1340,"bref":["Le lac Poopó est un ancien lac salin de Bolivie disparu fin 2015. Il était situé à environ 3 686 mètres d'altitude sur l'Altiplano à 75 km au sud d'Oruro, dans une région de climat aride.","Lorsqu'il était plein, sa superficie variait de 1 340 km2 à 2 500 km2, en faisant alors le second plus grand lac du pays après le lac Titicaca auquel il est indirectement relié. Sa profondeur moyenne était de 2,4 mètres. Il était sujet à de fortes variations du taux d'évaporation.","En 2002, il fut déclaré site Ramsar afin de le protéger. Cependant en raison de l'exploitation des eaux de ses émissaires à des fins agricoles et minières, le niveau du lac a rapidement baissé à partir de 2014 et a pratiquement disparu en décembre 2015, ne laissant que trois zones humides de quelques kilomètres carrés. La zone fut déclarée zone de désastre par le gouvernement bolivien."],"src":"https://fr.wikipedia.org/wiki/Lac_Poop%C3%B3","sw":"w","q":"Q464945","pays":["BO"],"c":["amerique-sud"]},"lac-poyang":{"n":"lac Poyang","t":"lac","km2":5100,"bref":["Le lac Poyang (chinois : 鄱阳湖 ; pinyin : póyáng hú) ou Po Yang Hu est un lac d’eau douce situé dans la province de Jiangxi."],"src":"https://fr.wikipedia.org/wiki/Lac_Poyang","sw":"w","q":"Q207690","pays":["CN"],"c":["asie"]},"lac-prespa":{"n":"lac Prespa","t":"lac","km2":273,"bref":["Le lac Prespa ou grand lac Prespa pour le distinguer du petit lac Prespa, en albanais Liqeni i Prespës, en grec Λίμνη Μεγάλη Πρέσπα / Limni Megáli Préspa, en macédonien Преспанско Езеро, Prespansko Ezero, est un lac partagé entre l'Albanie (38,8 km2), la Grèce (84,8 km2) et la Macédoine du Nord (190 km2). Il est situé à une altitude de 853 mètres."],"src":"https://fr.wikipedia.org/wiki/Lac_Prespa","sw":"w","q":"Q204392","pays":["MK","AL","GR"],"c":["europe"]},"lac-qinghai":{"n":"lac Qinghai","t":"lac","km2":4400,"bref":["Le lac Qinghai, est le plus grand lac de Chine, situé à 3 266 m d’altitude au nord du plateau tibétain.","Il se trouve pour sa rive sud dans le xian de Gonghe de la préfecture autonome tibétaine de Hainan et pour sa rive nord dans les xians de Haiyan et de Gangca de la préfecture autonome tibétaine de Haibei de la province du Qinghai, à laquelle il a donné son nom et dont la capitale, Xining, est située à 180 km à l'est du lac."],"src":"https://fr.wikipedia.org/wiki/Lac_Qinghai","sw":"w","q":"Q201294","pays":["CN"],"c":["asie"]},"lac-reindeer":{"n":"lac Reindeer","t":"lac","km2":6500,"bref":["Le lac Reindeer (anglais : Reindeer Lake), aussi connu sous le nom de lac du Caribou est un lac du centre du Canada situé à la frontière des provinces de Saskatchewan et du Manitoba. Le nom du lac provient probablement d'une traduction d'un mot algonquin. C'est le deuxième plus grand lac de la Saskatchewan et le neuvième du Canada. On y trouve beaucoup de petites îles. À l'est se trouve la municipalité de Kinoosao, au nord la municipalité de Brochet (Manitoba) et au sud celle de Southend (Saskatchewan).","Les eaux du lac s'écoulent principalement vers le sud par la rivière des Rennes et par une digue, se déversant ensuite dans le fleuve Churchill puis vers l'est dans la Baie d'Hudson.","Au sud du lac se trouve la baie profonde. Cette baie circulaire de 13 km de diamètre serait le vestige d'un impact de météorite il y a environ 100 millions d'années."],"src":"https://fr.wikipedia.org/wiki/Lac_Reindeer","sw":"w","q":"Q1134446","pays":["CA"],"c":["amerique-nord"]},"lac-sevan":{"n":"lac Sevan","t":"lac","km2":1271,"bref":["Le lac Sevan (en arménien Սևանա լիճ), mer / lac de Gegham (Գեղամա ծով / լիճ) en arménien classique, ou lac Gegharkuni (Գեղարքունի լիճ), est le plus grand lac d'Arménie, « véritable mer intérieure de 1 400 km2 (deux fois et demie le lac Léman) dotée du reste d'un régime à certains égards marin ». Il est le troisième plus grand lac d'Asie de l'Ouest après le lac d'Ourmia et le lac de Van.","Le lac Sevan est reconnu site Ramsar depuis le 7 juin 1993."],"src":"https://fr.wikipedia.org/wiki/Lac_Sevan","sw":"w","q":"Q181932","pays":["AM"],"c":["asie"]},"lac-superieur":{"n":"lac Supérieur","t":"lac","km2":82350,"bref":["Le lac Supérieur (en anglais lake Superior) est le plus grand des cinq Grands Lacs d'Amérique du Nord, sur la frontière entre les États-Unis et le Canada. Il est aussi le plus profond et le plus froid des cinq lacs. Son volume d'eau est supérieur à celui des quatre autre grands lacs réunis. Il a une superficie de 82 350 kilomètres carrés, qualité qui lui vaut d'être le plus grand lac du monde."],"src":"https://fr.vikidia.org/wiki/Lac_Sup%C3%A9rieur","sw":"v","q":"Q1066","pays":["CA","US"],"c":["amerique-nord"]},"lac-tai":{"n":"lac Tai","t":"lac","km2":2250,"bref":["Le lac Tai (chinois : 太湖 ; pinyin : tài hú ; litt. « le plus grand des lacs ») est un grand lac situé à proximité du delta du Yangzi Jiang, majoritairement dans la province du Jiangsu et à la limite avec celle du Zhejiang."],"src":"https://fr.wikipedia.org/wiki/Lac_Tai","sw":"w","q":"Q140712","pays":["CN"],"c":["asie"]},"lac-taimyr":{"n":"lac Taïmyr","t":"lac","km2":4560,"bref":["Le lac Taïmyr (en russe : Таймырское озеро, Taïmyrskoïe ozero) est un lac du kraï de Krasnoïarsk, en Russie.","Le lac se trouve dans la péninsule de Taïmyr, dans le bassin du fleuve Taïmyr, près des monts Byrranga et près de l’océan Arctique. Le lac Taïmyr est recouvert de glace de la fin de septembre à juin."],"src":"https://fr.wikipedia.org/wiki/Lac_Ta%C3%AFmyr","sw":"w","q":"Q845868","pays":["RU"],"c":["asie","europe"]},"lac-tana":{"n":"lac Tana","t":"lac","km2":2156,"bref":["Le lac Tana (transcrit parfois Tsana) est le plus grand lac d'Éthiopie, avec une surface supérieure à 3 000 km2 (70 km de largeur et 80 km de longueur). Situé à une altitude moyenne de 1 800 m, il s'est élevé à l'ère tertiaire, avec la surrection du bouclier arabo-éthiopien (unité tectonique entre l'Afrique de l'Est et la péninsule arabique)."],"src":"https://fr.wikipedia.org/wiki/Lac_Tana","sw":"w","q":"Q116685","pays":["ET"],"c":["afrique"]},"lac-tanganyika":{"n":"lac Tanganyika","t":"lac","km2":32900,"bref":["Le lac Tanganyika est un grand lac africain, il se situe au centre de l'Afrique dans le bras oriental du grand rift est-africain. Il est le premier lac constitué voici 9 à 12 millions d'années.","Celui-ci s'est formé à partir de trois bassins appelés Zongwe (ou Mpulungu), Kalemie et Kigoma."],"src":"https://fr.vikidia.org/wiki/Lac_Tanganyika","sw":"v","q":"Q5511","pays":["TZ","CD","BI","ZM"],"c":["afrique"]},"lac-tchad":{"n":"lac Tchad","t":"lac","km2":1540,"bref":["Le lac Tchad est un grand lac endoréique d'eau douce situé à la frontière entre le Niger (au nord-ouest), le Nigeria (au sud-ouest), le Cameroun (au sud) et le Tchad (à l'est). Le bassin hydrographique du lac couvre 7,8 % de la surface du continent, et alimente principalement le lac par le fleuve Chari, frontalier du Cameroun et du Tchad au sud-est.","Le lac abrite une grande diversité d'espèces, dont la prinia aquatique et l'alouette rousse, qui sont presque endémiques à la région. Au sud, la végétation bordant le bassin est majoritairement composée de papyrus, de Phragmites mauritianus et de Vossia cuspidata, tandis que le nord, légèrement plus salé, est bordé de roseau commun et de Typha australis. La salinité du lac reste basse, car les eaux chargées en sel quittent le lac par le sous-sol. Néanmoins, si l'apport hydrique du bassin nord reste faible, la salinité pourrait augmenter, et entraîner la disparition d'espèces."],"src":"https://fr.wikipedia.org/wiki/Lac_Tchad","sw":"w","q":"Q125309","pays":["TD","CM","NG","NE"],"c":["afrique"]},"lac-titicaca":{"n":"lac Titicaca","t":"lac","km2":8372,"bref":["Situé à la frontière de la Bolivie et du Pérou, le lac Titicaca est le plus grand lac d'Amérique latine et le plus haut lac navigable du monde. Il est partagé entre la Bolivie et le Pérou. Il est le centre mythologique de la civilisation des Incas."],"src":"https://fr.vikidia.org/wiki/Lac_Titicaca","sw":"v","q":"Q35342","pays":["PE","BO"],"c":["amerique-sud"]},"lac-trasimene":{"n":"lac Trasimène","t":"lac","km2":128,"bref":["Le lac Trasimène est un lac de l’Italie centrale. Par sa surface et son périmètre, il est le quatrième du pays (surface: 128 km2, circonférence : environ 40 km). C'est un lac naturellement endoréique, alimenté uniquement par les pluies et par quelques torrents, et qui n'a pas d'émissaires. Cependant, un canal le relie au Tibre depuis l'époque romaine.","Il est célèbre pour la bataille de Trasimène (-217) qui vit Hannibal Barca infliger une terrible défaite à l'armée romaine du consul Flaminius qui le poursuivait."],"src":"https://fr.wikipedia.org/wiki/Lac_Trasim%C3%A8ne","sw":"w","q":"Q188487","pays":["IT"],"c":["europe"]},"lac-ulemiste":{"n":"lac Ülemiste","t":"lac","km2":9,"bref":["Le lac Ülemiste (en estonien : Ülemiste järv) est un lac situé à Tallinn en Estonie."],"src":"https://fr.wikipedia.org/wiki/Lac_%C3%9Clemiste","sw":"w","q":"Q334761","pays":["EE"],"c":["europe"]},"lac-victoria":{"n":"lac Victoria","t":"lac","km2":68100,"bref":["Le lac Victoria est un grand lac situé en Afrique de l'Est, bordé par le Kenya (au nord-est), l'Ouganda (au nord et au nord-ouest) et par la Tanzanie (au sud).","Il fait partie des grands lacs africains."],"src":"https://fr.vikidia.org/wiki/Lac_Victoria","sw":"v","q":"Q5505","pays":["TZ","UG","KE"],"c":["afrique"]},"lac-vortsjarv":{"n":"lac Võrtsjärv","t":"lac","km2":269,"bref":["Le Lac Võrtsjärv est un lac eutrophique situé au centre de l'Estonie, entre les villes de Viljandi et de Tartu."],"src":"https://fr.wikipedia.org/wiki/Lac_V%C3%B5rtsj%C3%A4rv","sw":"w","q":"Q211516","pays":["EE"],"c":["europe"]},"lac-winnipeg":{"n":"Lac Winnipeg","t":"lac","km2":24400,"bref":["Le lac Winnipeg est un vaste lac du Canada, situé dans le centre-sud du Manitoba, une des provinces du pays. Son extrémité méridionale est située à quarante-neuf kilomètres de Winnipeg, capitale de la province. Le lac, situé à une altitude de 217 mètres, a une superficie de 23 750 kilomètres carrés et sa profondeur moyenne est de trente-six mètres. La distance à parcourir pour joindre les deux extrémités du lac s'élève à 442 kilomètres et la largeur maximale est de 109 kilomètres. La limite orientale du lac correspond à celle du Bouclier canadien qui ne s'amorce qu'à l'est et au nord du lac. Le principal centre de pêche et d'activités commerciales se trouve à Gimli. Le nom du lac provient de celui que lui donnaient les Amérindiens Cris : « wīnipēk » et qui signifie eau boueuse."],"src":"https://fr.vikidia.org/wiki/Lac_Winnipeg","sw":"v","q":"Q3272","pays":["CA"],"c":["amerique-nord"]},"lac-winnipegosis":{"n":"lac Winnipegosis","t":"lac","km2":5164,"bref":["Le lac Winnipegosis est un lac d’eau douce d’origine glacière qui se situe à 300 km au nord-ouest de la ville de Winnipeg dans la province centrale du Manitoba au Canada. Sa superficie de 5 370 km2 fait de lui le onzième lac du Canada et le troisième lac du Manitoba après le lac Winnipeg et le lac Manitoba."],"src":"https://fr.wikipedia.org/wiki/Lac_Winnipegosis","sw":"w","q":"Q934638","pays":["CA"],"c":["amerique-nord"]},"lac-zaissan":{"n":"lac Zaïssan","t":"lac","km2":1860,"bref":["Le lac Zaïssan (en kazakh et en russe : Зайсан) est un lac d’eau douce qui se trouve sur le cours de l'Irtych, à l’extrême est du Kazakhstan, entre les montagnes de l’Altaï au nord et celles du Tarbagataï au sud, près de la frontière chinoise."],"src":"https://fr.wikipedia.org/wiki/Lac_Za%C3%AFssan","sw":"w","q":"Q216621","pays":["KZ","CN"],"c":["asie","europe"]},"lagoa-dos-patos":{"n":"Lagoa dos Patos","t":"lac","km2":10000,"bref":["La lagoa dos Patos (aussi appelée laguna dos Patos par certains spécialistes), « lagune des Canards » en français, est la plus grande lagune d'Amérique du Sud. Elle se situe au Brésil, dans l’État du Rio Grande do Sul. Elle s'étend sur 265 km de longueur du nord-est au sud-ouest, parallèlement à l'océan Atlantique, sa superficie est de 10 144 km2."],"src":"https://fr.wikipedia.org/wiki/Lagoa_dos_Patos_(Rio_Grande_do_Sul)","sw":"w","q":"Q661235","pays":["BR"],"c":["amerique-sud"]},"loch-lomond":{"n":"loch Lomond","t":"lac","km2":71,"bref":["Le loch Lomond (en gaélique écossais : loch Laomainn) est un loch d'Écosse situé à l'ouest du pays, au sud des Highlands. Il fait partie à la fois des régions de Stirling, Argyll and Bute, et du West Dunbartonshire et se situe environ à 25 km au nord-ouest de Glasgow."],"src":"https://fr.wikipedia.org/wiki/Loch_Lomond","sw":"w","q":"Q208926","pays":["GB"],"c":["europe"]},"loch-ness":{"n":"loch Ness","t":"lac","km2":56,"bref":["Le loch Ness est un lac situé au Royaume-Uni, en Écosse. C'est un lac d'eau douce de forme très allongée. Le loch s'étend sur environ 39 km de long ; sa profondeur moyenne est de 133 m (profondeur maximale : 227 m) ; sa largeur varie de 1,2 à 3 km selon les marées, tandis que sa surface peut s'élever de près de 16 m.","Le loch est situé dans les Highlands, au sud-ouest de la ville d'Inverness et au nord-est de Fort Augustus.","La légende ou rumeur raconte qu'un monstre marin vit dans ce lac ; il est désigné par l'expression « monstre du Loch Ness » et surnommé familièrement Nessie.","https://www.radiofrance.fr/franceinter/podcasts/les-odyssees/l-histoire-du-monstre-du-loch-ness-3827278","57°17′20″N 4°27′45″O / 57.28889, -4.4625"],"src":"https://fr.vikidia.org/wiki/Loch_Ness","sw":"v","q":"Q49650","pays":["GB"],"c":["europe"]},"lough-neagh":{"n":"Lough Neagh","t":"lac","km2":392,"bref":["Le lough Neagh (en irlandais loch nEathach) est un lac situé au centre de l'Irlande du Nord.","La légende veut qu'il ait été formé par le géant Fionn Mac Cumhaill : en se battant contre un rival écossais, il arracha un morceau de terre (d'où le creux occupé par le lac) et le lui lança ; il rata sa cible et le morceau atterrit en pleine mer d'Irlande, créant ainsi l'île de Man."],"src":"https://fr.wikipedia.org/wiki/Lough_Neagh","sw":"w","q":"Q206942","pays":["GB"],"c":["europe"]},"saimaa":{"n":"Saimaa","t":"lac","km2":4400,"bref":["Le Saimaa, en suédois : Saimen, est un lac finlandais situé à proximité de la frontière russo-finlandaise, dans la province de Finlande-Orientale et la province de Finlande-Méridionale. Le lac est parsemé d'îles, et d'étroits canaux divisent le lac en plusieurs sous-bassins, chacun doté d'un nom qui lui est propre. Parmi les sous-bassins les plus importants, on compte Suur-Saimaa, Orivesi, Puruvesi, Haukivesi, Yövesi, Pihlajavesi, Luonteri et Pyhäselkä.","Le Saimaa, avec son émissaire la Vuoksi, forme un bassin hydrographique de 66 700 km2, par ailleurs sous-bassin du bassin du lac Ladoga."],"src":"https://fr.wikipedia.org/wiki/Saimaa_(lac)","sw":"w","q":"Q192770","pays":["FI"],"c":["europe"]},"tonle-sap":{"n":"Tonlé Sap","t":"lac","km2":2700,"bref":["Le Tonlé Sap (en khmer : បឹងទន្លេសាប, Boeung Tonlé Sap, « grande rivière d'eau douce », traduit plus fréquemment « grand lac ») est un système hydrologique combinant lac et rivière portant ce même nom, d'une importance capitale pour le Cambodge. Le lac est le plus grand lac d'eau douce d'Asie du Sud-Est et un site de première importance du point de vue écologique, reconnu en tant que réserve de biosphère par l'Unesco en 1997. Le lac est situé en plein centre du Cambodge, avec une orientation nord-ouest sud-est. Le site historique d'Angkor se trouve tout près de son bord nord. L'émissaire du même nom et de même orientation relie le lac au Mékong, le confluent étant à Phnom Penh.","Le lac occupe une dépression créée par la contrainte géologique causée par la collision du sous-continent indien et de l'Asie."],"src":"https://fr.wikipedia.org/wiki/Tonl%C3%A9_Sap","sw":"w","q":"Q199938","pays":["KH"],"c":["asie"]},"vanern":{"n":"Vänern","t":"lac","km2":5650,"bref":["Le Vänern est le plus grand lac de Suède en superficie (5 648 km2) et en volume (153 km3). Il est situé dans la partie méridionale de la Suède.","Il est le troisième lac européen par ordre d'importance (après les lacs russes Ladoga et Onega)."],"src":"https://fr.wikipedia.org/wiki/V%C3%A4nern","sw":"w","q":"Q173596","pays":["SE"],"c":["europe"]},"vattern":{"n":"Vättern","t":"lac","km2":1893,"bref":["Le Vättern, situé au centre de la Suède méridionale, est le second lac de Suède en superficie, après le Vänern."],"src":"https://fr.wikipedia.org/wiki/V%C3%A4ttern","sw":"w","q":"Q188195","pays":["SE"],"c":["europe"]},"yssyk-koul":{"n":"Yssyk Koul","t":"lac","km2":6236,"bref":["L'Issyk-Koul, parfois autrefois Issygh koul (en russe : Иссык-Куль), ou Ysyk-Köl (en kirghiz : Ысык-Көл, « lac chaud ») est un lac endoréique salé situé en Asie centrale dans le nord des monts Tian Shan dans le nord-est du Kirghizistan, dans la province de l'Yssyk-Köl.","Huitième lac le plus profond avec ses 668 m de profondeur, c'est aussi le onzième plus grand lac en termes de volume au monde ainsi que le deuxième plus grand lac de montagne avec ses 6 280 km2. C'est l'un des plus vieux lacs du monde, formé il y a environ 25 millions d'années par l'affaissement du sol. Bien qu'il soit situé à 1 606 m d'altitude avec un climat continental rude, il gèle rarement en raison de sa légère salinité, ce qui lui vaut le nom en kirghize de lac chaud. Classé en 1974 comme site Ramsar d'importance mondiale grâce à sa biodiversité, il est inclus dans la réserve de biosphère de l'Issyk-Koul depuis 2001."],"src":"https://fr.wikipedia.org/wiki/Yssyk_Koul","sw":"w","q":"Q42191","pays":["KG"],"c":["asie"]}}
});
